const GAME_CAP = { minecraft: 'game_minecraft', mcservidor: 'game_mcservidor', mcparkour: 'game_mcparkour', mckoth: 'game_mckoth', mcfarm: 'game_mcfarm', mcshooter: 'game_mcshooter', bedrock: 'game_bedrock', sandbox: 'game_sandbox', roblox: 'game_roblox', roblox3: 'game_roblox3', mariobros: 'game_mariobros', smb3: 'game_smb3', smw: 'game_smw', mari0: 'game_mari0', plantasvszombies: 'game_plantasvszombies', pvzhybrid: 'game_pvzhybrid', repo: 'game_repo', l4d: 'game_l4d', unturned: 'game_unturned', gtavkoth: 'game_gtavkoth', gtavchaos: 'game_gtavchaos', gtavchiliad: 'game_gtavchiliad', crashctr: 'game_crashctr', metalslug: 'game_metalslug', geometrydash: 'game_geometrydash' };
// Minijuegos visibles pero aún no disponibles (solo el admin puede entrar).
const GAME_COMING_SOON = {};

window.CAPS = { plan: 'free', limits: {}, features: {} };
function setCaps(c) {
  if (!c) return;
  const plan = c.plan || window.MY_PLAN || window.CAPS?.plan || 'free';
  window.CAPS = {
    plan,
    limits: c.limits || {},
    features: c.features || {},
    spotify: typeof c.spotify === 'boolean' ? c.spotify : !!window.CAPS?.spotify,
  };
  if (plan && plan !== 'free') {
    const cur = String(window.MY_PLAN || '').toLowerCase();
    // caps.plan es el bucket (premium/free); no pisar etiqueta Founder
    if (!(cur === 'founder' && (plan === 'premium' || plan === 'admin'))) {
      window.MY_PLAN = plan === 'admin' ? 'premium' : plan;
    }
  }
  if (typeof c.spotify === 'boolean') window.SPOTIFY_ACCESS = c.spotify;
  applyCaps();
  try { revealWebhookTab(); } catch {}
  try { revealConfigTab(); } catch {}
  try { revealJuegosTab(); } catch {}
  try { revealSpotifyTab(); } catch {}
  if (typeof spotifyTabVisible === 'function' && spotifyTabVisible() && typeof setupSpotifyUI === 'function') {
    try { setupSpotifyUI(); } catch {}
  }
  try { applySpotifyLock(); } catch {}
  try { if (typeof refreshDockPlanUi === 'function') refreshDockPlanUi(); } catch {}
}
function capLimit(key) {
  const n = window.CAPS?.limits?.[key];
  return Number.isFinite(n) ? n : Infinity;
}
function capFeature(key) {
  const f = window.CAPS?.features;
  if (!f) return true;            // sin info -> permitir (admin / aún cargando)
  return f[key] !== false;
}

/** Editor Pro: solo VIP (premium) / Founder / admin. */
function editorRapidoUnlocked() {
  if (window.IS_ADMIN) return true;
  if (typeof capFeature === 'function' && capFeature('tab_editor_rapido')) return true;
  const plan = String(window.CAPS?.plan || window.MY_PLAN || '').toLowerCase();
  return plan === 'premium' || plan === 'admin' || plan === 'founder';
}
window.editorRapidoUnlocked = editorRapidoUnlocked;
function planCountOf(kind) {
  return (settings?.[kind] || []).length;
}
// Devuelve true si todavía se puede añadir; si no, avisa y devuelve false.
function ensureCanAdd(kind, limitKey, nounPlural) {
  const lim = capLimit(limitKey);
  if (planCountOf(kind) >= lim) {
    toast(`Tu plan ${window.CAPS.plan === 'premium' ? 'Premium' : 'Gratis'} permite hasta ${lim} ${nounPlural}.`, 'warn');
    return false;
  }
  return true;
}

function syncNavSections() {
  const nav = document.querySelector('.nav');
  if (!nav) return;
  nav.querySelectorAll('.nav-section').forEach((sec) => {
    const visible = [...sec.querySelectorAll('.nav-item')].some(navItemVisible);
    sec.hidden = !visible;
  });
  nav.querySelectorAll('.nav-divider').forEach((div) => {
    const prev = div.previousElementSibling;
    const next = div.nextElementSibling;
    const prevOk = prev?.classList.contains('nav-section') && !prev.hidden;
    const nextOk = next?.classList.contains('nav-section') && !next.hidden;
    div.hidden = !(prevOk && nextOk);
  });
}

function navItemVisible(btn) {
  if (!btn) return false;
  return getComputedStyle(btn).display !== 'none';
}

// Aplica las capacidades a la interfaz: oculta pestañas/overlays bloqueados,
// muestra avisos de límite y desactiva botones de "crear" si se llegó al tope.
/** Candado en ítem del dock (pestaña visible pero bloqueada por plan). */
function setNavItemPlanLock(btn, locked) {
  if (!btn) return;
  btn.classList.toggle('nav-item-plan-locked', !!locked);
  let badge = btn.querySelector('.nav-plan-lock');
  if (!locked) {
    badge?.remove();
    if (btn.getAttribute('title') === 'Solo Premium — VIP / Founder') btn.removeAttribute('title');
    return;
  }
  if (!badge) {
    badge = document.createElement('span');
    badge.className = 'nav-plan-lock';
    badge.setAttribute('aria-hidden', 'true');
    badge.textContent = '🔒';
    btn.appendChild(badge);
  }
  btn.title = 'Solo Premium — VIP / Founder';
}

/** Editor Pro: visible para free, con candado en menú + overlay en la vista. */
function applyEditorRapidoLock() {
  const locked = typeof editorRapidoUnlocked === 'function' ? !editorRapidoUnlocked() : false;
  const view = document.getElementById('view-editor-rapido');
  const lock = document.getElementById('er-premium-lock');
  const nav = document.getElementById('navEditorRapido')
    || document.querySelector('.nav-item[data-view="editor-rapido"]');
  if (view) view.classList.toggle('is-er-locked', locked);
  if (lock) lock.hidden = !locked;
  setNavItemPlanLock(nav, locked);
  const up = document.getElementById('er-premium-upgrade');
  if (up && !up._erPlanWired) {
    up._erPlanWired = true;
    up.addEventListener('click', (e) => {
      e.preventDefault();
      document.querySelector('.nav-item[data-view="planes"]')?.click();
    });
  }
}
window.applyEditorRapidoLock = applyEditorRapidoLock;

function applyCaps() {
  try { syncHomeHeroPlan(); } catch {}
  try { updateVideosAiLocks(); } catch {}
  try { applyEditorRapidoLock(); } catch {}
  if (window.IS_ADMIN) return; // el admin lo ve todo
  // Pestañas del menú lateral
  document.querySelectorAll('.nav-item[data-view]').forEach((btn) => {
    const cap = TAB_CAP[btn.dataset.view];
    if (!cap) return;
    // Editor Pro: no ocultar; se muestra con candadito (VIP / Founder).
    if (btn.dataset.view === 'editor-rapido') {
      btn.style.display = '';
      return;
    }
    btn.style.display = capFeature(cap) ? '' : 'none';
  });
  try { syncNavSections(); } catch {}
  // Overlays individuales: si no están en el plan, NO se ocultan; se muestran con
  // un bloqueo "Solo Premium" por encima (la tarjeta sigue visible pero no usable).
  document.querySelectorAll('.ov-url[data-path]').forEach((code) => {
    const base = String(code.dataset.path).split('?')[0];
    const cap = OVERLAY_CAP[base];
    if (!cap) return;
    const card = code.closest('.ovpro-card') || code.closest('.overlay-item') || code.closest('.ov-card');
    if (card) setOverlayLock(card, !capFeature(cap));
  });
  // Minijuegos (pestaña Juegos): bloqueo por plan o "Próximamente".
  document.querySelectorAll('#view-juegos .juego-card[data-game]').forEach((card) => {
    updateGameCardLock(card);
  });
  // Voces TTS de servidor: Edge español (todos los países) siempre; TikTok/Disney según plan.
  syncTtsServerVoicePlanUi();
  // Avisos de límite + botones de crear
  applyLimitUI();
  renderPlanView();
}

function isVideosAiLocked() {
  if (window.IS_ADMIN) return false;
  return !capFeature('videos_ai');
}

function setAudioOptLock(btn, locked) {
  if (!btn) return;
  btn.classList.toggle('ao-locked', !!locked);
  let ov = btn.querySelector('.ao-lock-overlay');
  if (!locked) {
    ov?.remove();
    return;
  }
  if (ov) return;
  ov = document.createElement('div');
  ov.className = 'ao-lock-overlay';
  ov.innerHTML = `<span class="ao-lock-ico">🔒</span><span class="ao-lock-title">⭐ Solo Premium</span>`;
  ov.addEventListener('click', (e) => {
    e.preventDefault();
    e.stopPropagation();
    toast('Videos AI es Solo Premium. Mejora tu plan para usarlo ⭐', 'warn');
  });
  btn.appendChild(ov);
}

function updateVideosAiLocks() {
  const locked = isVideosAiLocked();
  setAudioOptLock($('vid-libbtn'), locked);
  setAudioOptLock($('ba-libbtn'), locked);
}

