/* ---- Anuncios (campana + admin) ---- */
let annCache = [];

function annSeenKey() { return `livecoins_ann_seen_${window.MY_USER || 'default'}`; }
function annSeenAt() { return Number(localStorage.getItem(annSeenKey()) || 0); }

function annEsc(s) {
  return String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function formatAnnDate(ts) {
  if (!ts) return '';
  return new Date(ts).toLocaleDateString('es', { day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' });
}

function updateAnnDot() {
  const dot = document.getElementById('annDot');
  if (!dot) return;
  const seen = annSeenAt();
  dot.hidden = !annCache.some((a) => (a.createdAt || 0) > seen);
}

function markAnnSeen() {
  const latest = annCache.reduce((m, a) => Math.max(m, a.createdAt || 0), 0);
  if (latest > 0) localStorage.setItem(annSeenKey(), String(latest));
  updateAnnDot();
  renderAnnList();
}

function renderAnnList() {
  const list = document.getElementById('annPopList');
  if (!list) return;
  if (!annCache.length) {
    list.innerHTML = '<p class="ann-empty">No hay anuncios por ahora.</p>';
    return;
  }
  const seen = annSeenAt();
  list.innerHTML = annCache.map((a) => `
    <article class="ann-item${(a.createdAt || 0) > seen ? ' unread' : ''}">
      <div class="ann-item-title">${annEsc(a.title || 'Anuncio')}</div>
      <div class="ann-item-msg">${annEsc(a.message || '')}</div>
      <div class="ann-item-date">${formatAnnDate(a.createdAt)}</div>
    </article>
  `).join('');
}

function renderHomeAnnList() {
  /* Legacy no-op: la tarjeta de inicio ahora usa novedades de la app. */
}

async function loadHomeAppNews() {
  const list = document.getElementById('home-ann-list');
  const verBadge = document.getElementById('home-app-ver');
  if (!list) return;
  try {
    const r = await fetch('/api/app-version', { cache: 'no-store' });
    if (!r.ok) throw new Error('fail');
    const d = await r.json();
    const version = String(d.version || '').trim();
    const notes = String(d.notes || '').trim();
    const updatedAt = Number(d.updatedAt) || 0;
    if (verBadge) {
      if (version) {
        verBadge.hidden = false;
        verBadge.textContent = `v${version}`;
      } else {
        verBadge.hidden = true;
        verBadge.textContent = '';
      }
    }
    if (!version && !notes) {
      list.innerHTML = '<p class="home-ann-empty">Aún no hay novedades de la app.</p>';
      return;
    }
    const lines = notes
      ? notes.split(/\r?\n/).map((s) => s.trim()).filter(Boolean).slice(0, 6)
      : [];
    const body = lines.length
      ? `<ul class="home-app-notes">${lines.map((l) => `<li>${annEsc(l)}</li>`).join('')}</ul>`
      : '<div class="home-ann-item-msg">Nueva versión publicada.</div>';
    list.innerHTML = `
      <article class="home-ann-item home-ann-item--app">
        <div class="home-ann-item-title">${version ? `Actualización ${annEsc(version)}` : 'Actualización'}</div>
        ${body}
        ${updatedAt ? `<div class="home-ann-item-date">${formatAnnDate(updatedAt)}</div>` : ''}
      </article>`;
  } catch {
    list.innerHTML = '<p class="home-ann-empty">No se pudieron cargar las novedades de la app.</p>';
    if (verBadge) { verBadge.hidden = true; verBadge.textContent = ''; }
  }
}

async function loadAnnouncements() {
  try {
    const r = await fetch('/api/announcements', { credentials: 'same-origin', cache: 'no-store' });
    if (!r.ok) return;
    const d = await r.json();
    annCache = Array.isArray(d.announcements) ? d.announcements : [];
    updateAnnDot();
    if (document.getElementById('annPop') && !document.getElementById('annPop').hidden) renderAnnList();
  } catch {}
}

function toggleAnnPop(open) {
  const pop = document.getElementById('annPop');
  if (!pop) return;
  const show = open ?? pop.hidden;
  pop.hidden = !show;
  if (show) {
    renderAnnList();
    markAnnSeen();
  }
}

