/** Carrusel Inicio: 2 promos, auto cada 5s + dots (sin flechas). */
function setupHomePromoCarousel() {
  const root = document.getElementById('homePromoSilla');
  if (!root || root.dataset.carouselReady === '1') return;
  const slides = Array.from(root.querySelectorAll('.home-promo-slide'));
  const dots = Array.from(root.querySelectorAll('.home-promo-dot'));
  if (slides.length < 2) return;
  root.dataset.carouselReady = '1';
  let idx = Math.max(0, slides.findIndex((s) => s.classList.contains('is-active')));
  if (idx < 0) idx = 0;
  let timer = null;
  const INTERVAL_MS = 5000;

  function show(next) {
    const n = ((next % slides.length) + slides.length) % slides.length;
    idx = n;
    slides.forEach((s, i) => s.classList.toggle('is-active', i === n));
    dots.forEach((d, i) => {
      const on = i === n;
      d.classList.toggle('is-active', on);
      d.setAttribute('aria-selected', on ? 'true' : 'false');
    });
  }
  function restart() {
    if (timer) clearInterval(timer);
    timer = setInterval(() => show(idx + 1), INTERVAL_MS);
  }

  dots.forEach((d) => {
    d.addEventListener('click', (e) => {
      e.preventDefault();
      const n = Number(d.getAttribute('data-dot'));
      if (!Number.isFinite(n)) return;
      show(n);
      restart();
    });
  });

  root.querySelectorAll('.home-promo-cta').forEach((a) => {
    a.addEventListener('click', (e) => {
      const url = a.getAttribute('href');
      if (!url) return;
      e.preventDefault();
      openExternalLink(url);
    });
  });

  root.addEventListener('mouseenter', () => { if (timer) { clearInterval(timer); timer = null; } });
  root.addEventListener('mouseleave', restart);
  document.addEventListener('visibilitychange', () => {
    if (document.hidden) {
      if (timer) { clearInterval(timer); timer = null; }
    } else restart();
  });
  show(idx);
  restart();
}

async function loadAnnouncementsAdmin() {
  const list = document.getElementById('ann-admin-list');
  if (!list) return;
  try {
    const r = await fetch('/api/announcements', { credentials: 'same-origin', cache: 'no-store' });
    if (!r.ok) { list.innerHTML = '<p class="tts-sub">Sin acceso.</p>'; return; }
    const d = await r.json();
    const items = Array.isArray(d.announcements) ? d.announcements : [];
    if (!items.length) { list.innerHTML = '<p class="tts-sub">Aún no hay anuncios publicados.</p>'; return; }
    list.innerHTML = items.map((a) => `
      <div class="ann-admin-item">
        <div class="ann-admin-item-body">
          <div class="ann-admin-item-title">${annEsc(a.title)}</div>
          <div class="ann-admin-item-msg">${annEsc(a.message)}</div>
          <div class="ann-admin-item-date">${formatAnnDate(a.createdAt)}</div>
        </div>
        <button type="button" class="btn tiny ghost ann-admin-del" data-id="${annEsc(a.id)}">Eliminar</button>
      </div>
    `).join('');
    list.querySelectorAll('.ann-admin-del').forEach((b) => {
      b.onclick = async () => {
        if (!confirm('¿Eliminar este anuncio?')) return;
        b.disabled = true;
        try {
          const dr = await fetch('/api/admin/announcements/delete', {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ id: b.dataset.id }),
          });
          if (dr.ok) { loadAnnouncementsAdmin(); loadAnnouncements(); }
        } catch {} finally { b.disabled = false; }
      };
    });
  } catch {
    list.innerHTML = '<p class="tts-sub">Error al cargar.</p>';
  }
}

