function renderPlansEditor() {
  const editor = document.getElementById('plans-editor');
  if (!editor || !plansCatalog || !plansConfig) return;
  const plan = plansConfig[plansActiveTab] || { limits: {}, features: {} };
  const esc = (s) => String(s).replace(/"/g, '&quot;');

  const limitsHtml = plansCatalog.limits.map((c) => `
    <div class="plan-limit">
      <label>${c.label}</label>
      <input type="number" min="0" max="9999" data-limit="${c.key}" value="${Number(plan.limits[c.key] ?? 0)}">
    </div>`).join('');

  const groupHtml = (title, items) => `
    <div class="plan-group">
      <h4>${title}</h4>
      <div class="plan-feats">
        ${items.map((c) => `
          <label class="plan-feat">
            <input type="checkbox" data-feat="${c.key}" ${plan.features[c.key] !== false ? 'checked' : ''}>
            <span>${esc(c.label)}</span>
          </label>`).join('')}
      </div>
    </div>`;

  editor.innerHTML = `
    <div class="plan-group">
      <h4>Límites (cantidad máxima)</h4>
      <div class="plan-limits">${limitsHtml}</div>
    </div>
    ${groupHtml('Pestañas del panel', plansCatalog.tabs)}
    ${plansCatalog.games && plansCatalog.games.length ? groupHtml('Juegos', plansCatalog.games) : ''}
    ${groupHtml('Overlays', plansCatalog.overlays)}
    ${groupHtml('Extras', plansCatalog.extras)}
  `;
}

// Recoge los valores del editor hacia plansConfig[plansActiveTab].
function collectPlansEditor() {
  const editor = document.getElementById('plans-editor');
  if (!editor || !plansConfig) return;
  const plan = plansConfig[plansActiveTab] || (plansConfig[plansActiveTab] = { limits: {}, features: {} });
  editor.querySelectorAll('input[data-limit]').forEach((inp) => {
    let v = Number(inp.value);
    if (!Number.isFinite(v) || v < 0) v = 0;
    plan.limits[inp.dataset.limit] = v;
  });
  editor.querySelectorAll('input[data-feat]').forEach((inp) => {
    plan.features[inp.dataset.feat] = inp.checked;
  });
}

document.querySelectorAll('.plan-tab').forEach((tab) => {
  tab.onclick = () => {
    collectPlansEditor(); // guarda lo editado de la pestaña actual antes de cambiar
    document.querySelectorAll('.plan-tab').forEach((t) => t.classList.remove('active'));
    tab.classList.add('active');
    plansActiveTab = tab.dataset.plan;
    renderPlansEditor();
  };
});

const plansSaveBtn = document.getElementById('plans-save');
if (plansSaveBtn) plansSaveBtn.onclick = async () => {
  collectPlansEditor();
  const status = document.getElementById('plans-status');
  plansSaveBtn.disabled = true;
  if (status) status.textContent = 'Guardando…';
  try {
    const r = await fetch('/api/admin/plans', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(plansConfig),
    });
    if (r.ok) {
      const d = await r.json();
      if (d.config) plansConfig = d.config;
      // Refleja los cambios al instante en la pestaña "Planes" (tarjetas + comparación),
      // sin esperar al mensaje del WebSocket.
      if (d.config) {
        if (planCompareData) planCompareData.config = d.config;
        else planCompareData = { catalog: plansCatalog, config: d.config };
        renderPlanView();
      }
      if (d.localOnly) {
        if (status) status.textContent = 'Guardado solo en esta PC';
        toast('⚠️ Sin sesión en la nube: los planes se guardaron SOLO en esta PC. Vuelve a iniciar sesión para sincronizar con Render.', 'warn');
      } else {
        if (status) status.textContent = 'Guardado ✓';
        toast('Planes guardados.');
      }
    } else {
      if (status) status.textContent = 'Error al guardar';
    }
  } catch {
    if (status) status.textContent = 'Error al guardar';
  }
  plansSaveBtn.disabled = false;
  setTimeout(() => { if (status) status.textContent = ''; }, 2500);
};

/* ====================== Panel ====================== */
function fmt(n) {
  if (n >= 1_000_000) return (n / 1_000_000).toFixed(1) + 'M';
  if (n >= 1_000) return (n / 1_000).toFixed(1) + 'K';
  return String(n ?? 0);
}

let connectStreamerPhoto = '';

function connectAvatarUrl(photo) {
  if (!photo) return '';
  if (/^https?:\/\//i.test(photo) && !photo.startsWith(location.origin)) {
    return '/api/img-proxy?url=' + encodeURIComponent(photo);
  }
  return photo;
}

function updateConnectAvatar({ photo, nickname, username, live } = {}) {
  const wrap = document.getElementById('connectAv');
  const img = document.getElementById('connectAvImg');
  const ph = document.getElementById('connectAvPh');
  if (!wrap || !img || !ph) return;
  if (photo) connectStreamerPhoto = photo;
  const name = nickname || username || $('username')?.value || '';
  const url = connectAvatarUrl(photo || connectStreamerPhoto);
  wrap.classList.toggle('live', !!live);
  if (url) {
    img.referrerPolicy = 'no-referrer';
    img.src = url;
    img.hidden = false;
    ph.hidden = true;
    img.onerror = () => {
      img.hidden = true;
      ph.hidden = false;
      ph.textContent = initial(name);
    };
  } else {
    img.hidden = true;
    ph.hidden = false;
    ph.textContent = initial(name || '?');
  }
  try { updateDockUserAvatar({ photo: photo || connectStreamerPhoto, nickname: name, username: username || window.MY_USER }); } catch {}
}

function renderState(s) {
  $('s-viewers').textContent = fmt(s.stats.viewers);
  $('s-likes').textContent = fmt(s.stats.likes);
  $('s-diamonds').textContent = fmt(s.stats.diamonds);
  $('s-gifts').textContent = fmt(s.stats.gifts);
  $('s-comments').textContent = fmt(s.stats.comments);
  $('s-follows').textContent = fmt(s.stats.follows);
  $('s-shares').textContent = fmt(s.stats.shares);
  $('s-joins').textContent = fmt(s.stats.joins);

  const dot = $('dot'), st = $('statusText'), badge = $('liveBadge');
  const btnC = $('btnConnect'), btnD = $('btnDisconnect');
  if (s.connected) {
    dot.className = 'dot live'; st.textContent = `En vivo · @${s.username}`;
    badge.className = 'live-badge live'; badge.textContent = `● En vivo · @${s.username}`;
    if (btnC) { btnC.hidden = true; btnC.disabled = false; btnC.textContent = 'Conectar'; btnC.classList.remove('is-connecting'); }
    if (btnD) btnD.hidden = false;
  } else if (s.connecting) {
    dot.className = 'dot wait'; st.textContent = `Conectando...`;
    badge.className = 'live-badge wait'; badge.textContent = '● Conectando...';
    if (btnC) { btnC.hidden = false; btnC.disabled = true; btnC.textContent = 'Conectando…'; btnC.classList.add('is-connecting'); }
    if (btnD) btnD.hidden = true;
  } else {
    dot.className = 'dot off';
    if (s.autoConnect && s.username) {
      // Auto-conexión activa: aún no estás en vivo, el servidor reintenta solo.
      st.textContent = `Esperando tu live · @${s.username}`;
      badge.className = 'live-badge off'; badge.textContent = '● Esperando tu live';
    } else {
      st.textContent = 'Desconectado';
      badge.className = 'live-badge off'; badge.textContent = '● Desconectado';
    }
    if (btnC) { btnC.hidden = false; btnC.disabled = false; btnC.textContent = 'Conectar'; btnC.classList.remove('is-connecting'); }
    if (btnD) btnD.hidden = true;
  }
  if (s.username && !$('username').value) $('username').value = s.username;
  if (s.username) setLastTikTokUserPref(s.username);
  updateConnectAvatar({
    photo: s.photo,
    nickname: s.nickname,
    username: s.username,
    live: !!s.connected,
  });
  // Leaderboard solo si Inicio/panel está visible (evita innerHTML en otras pestañas)
  const panelView = document.getElementById('view-panel');
  if (!panelView || panelView.classList.contains('active')) {
    renderLeaderboard(s.topGifters || []);
  }
  try { updateHomeWelcome(s); } catch {}
}

let lastLeaderboardSig = '';
function renderLeaderboard(list) {
  const el = $('leaderboard');
  const countEl = document.getElementById('lb-count');
  const rows = Array.isArray(list) ? list : [];
  if (countEl) countEl.textContent = String(rows.length || 0);
  const sig = rows.length
    ? rows.map((g) => `${g.uniqueId || g.nickname || ''}:${g.diamonds || 0}`).join('|')
    : '';
  if (sig === lastLeaderboardSig && el && el.children.length) return;
  lastLeaderboardSig = sig;
  if (!rows.length) {
    el.innerHTML = `<div class="feed-empty" data-empty="leaderboard">
      <span class="feed-empty-ico" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M8 21h8"/><path d="M12 17v4"/><path d="M7 4h10v4a5 5 0 0 1-10 0V4z"/></svg></span>
      <div class="feed-empty-tt">Ranking vacío</div>
      <div class="feed-empty-dx">El top por diamantes se llenará durante el live.</div>
    </div>`;
    return;
  }
  el.innerHTML = rows.map((g, i) => {
    const topCls = i === 0 ? ' is-top1' : i === 1 ? ' is-top2' : i === 2 ? ' is-top3' : '';
    return `<div class="lb-row${topCls}"><div class="rank">${i + 1}</div>${avatar(g)}
      <div class="nm">${esc(g.nickname)}</div><div class="dm">${fmt(g.diamonds)} 💎</div></div>`;
  }).join('');
}

function avatar(u) {
  if (u.photo) return `<img class="av" src="${esc(u.photo)}" onerror="this.replaceWith(Object.assign(document.createElement('div'),{className:'ph',textContent:'${initial(u.nickname)}'}))" />`;
  return `<div class="ph">${initial(u.nickname)}</div>`;
}
function initial(n) { return (n || '?').trim().charAt(0).toUpperCase(); }

const FEED_EMPTY_HTML = {
  chat: `<div class="feed-empty" data-empty="chat">
    <span class="feed-empty-ico" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg></span>
    <div class="feed-empty-tt">Esperando mensajes</div>
    <div class="feed-empty-dx">El chat aparecerá aquí cuando conectes tu live.</div>
  </div>`,
  gifts: `<div class="feed-empty" data-empty="gifts">
    <span class="feed-empty-ico" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><rect x="3" y="8" width="18" height="13" rx="1"/><path d="M12 8v13"/><path d="M19 8a3 3 0 0 0-3-3c-2 0-3 3-4 3s-2-3-4-3a3 3 0 0 0-3 0"/></svg></span>
    <div class="feed-empty-tt">Sin regalos aún</div>
    <div class="feed-empty-dx">Cuando alguien envíe un regalo, se listará aquí.</div>
  </div>`,
  events: `<div class="feed-empty" data-empty="events">
    <span class="feed-empty-ico" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><circle cx="12" cy="12" r="3"/><path d="M12 1v2M12 21v2M4.2 4.2l1.4 1.4M18.4 18.4l1.4 1.4M1 12h2M21 12h2"/></svg></span>
    <div class="feed-empty-tt">Sin eventos</div>
    <div class="feed-empty-dx">Conexiones, follows y avisos del sistema saldrán aquí.</div>
  </div>`,
};

/** Filas activas de rachas en el feed Regalos (una por usuario+regalo). */
const activeGiftFeedRows = new Map();
let lastGiftFeedSig = '';
let lastGiftFeedAt = 0;

function feedCountId(feedId) {
  if (feedId === 'chat') return 'chat-count';
  if (feedId === 'gifts') return 'gifts-count';
  if (feedId === 'events') return 'events-count';
  return '';
}

function updateFeedCount(feedId) {
  const feed = $(feedId);
  const id = feedCountId(feedId);
  const el = id ? document.getElementById(id) : null;
  if (!feed || !el) return;
  let n = 0;
  for (let i = 0; i < feed.children.length; i++) {
    if (feed.children[i].classList && feed.children[i].classList.contains('row')) n++;
  }
  el.textContent = String(n);
}

/** Quita las filas más antiguas cuando el feed supera MAX_ROWS (una sola pasada). */
function trimFeedRows(feed) {
  if (!feed) return;
  // children es más barato que querySelectorAll('.row') en cada mensaje
  let rowCount = 0;
  for (let i = 0; i < feed.children.length; i++) {
    if (feed.children[i].classList && feed.children[i].classList.contains('row')) rowCount++;
  }
  let excess = rowCount - MAX_ROWS;
  if (excess <= 0) return;
  let i = 0;
  while (excess > 0 && i < feed.children.length) {
    const row = feed.children[i];
    if (!row.classList || !row.classList.contains('row')) { i++; continue; }
    const k = row.dataset && row.dataset.giftKey;
    if (k) activeGiftFeedRows.delete(k);
    row.remove();
    excess--;
    // no incrementar i: el siguiente hijo ocupa el mismo índice
  }
}

function pushRow(feedId, html, cls = '') {
  const feed = $(feedId);
  if (!feed) return;
  feed.querySelector('.feed-empty')?.remove();
  feed.querySelector('.empty')?.remove();
  const div = document.createElement('div');
  div.className = `row ${cls}`;
  div.innerHTML = html;
  feed.appendChild(div);
  trimFeedRows(feed);
  feed.scrollTop = feed.scrollHeight;
  updateFeedCount(feedId);
}
function addChat(p) {
  ttsTrackChatUser(p);
  const lvl = Number(p.memberLevel) || 0;
  const lvlTag = lvl > 0 ? `<span class="chat-lvl" title="Nivel miembro club de fans">Nv.${lvl}</span>` : '';
  const dLvl = Number(p.donorLevel) || 0;
  const donorTitle = p.donorSource === 'tiktok' ? 'Nivel donador TikTok (regalos globales)' : 'Nivel donador (puntos en tu canal)';
  const donorTag = dLvl > 0 ? `<span class="chat-donlvl" title="${donorTitle}">⭐${dLvl}</span>` : '';
  pushRow('chat', `${avatar(p)}<div><span class="name">${esc(p.nickname)}</span>${lvlTag}${donorTag}<span class="text">${esc(p.comment)}</span></div>`);
}

// Respuesta automática de un comando personalizado: se muestra en el chat del panel
// y se lee en voz alta (respetando la voz/idioma configurados en Chat TTS).
function handleBotReply(p) {
  const text = String(p?.text || '').trim();
  if (!text) return;
  pushRow('chat', `<div class="ph bot-ava">🤖</div><div><span class="name bot-name">Bot · ${esc(p.command || '')}</span><span class="text">${esc(text)}</span></div>`, 'bot');
  // Solo se lee en voz alta si el TTS está activado (respeta el interruptor y su advertencia).
  if (settings?.tts?.enabled) ttsSpeakText(text);
}
function giftImageOf(p) {
  if (p.image) return p.image;
  if (p.giftId) return giftCatalogById.get(String(p.giftId))?.image || '';
  if (p.giftName) return giftCatalog.find((x) => x.name.toLowerCase() === String(p.giftName).toLowerCase())?.image || '';
  return '';
}

function giftFeedRowHtml(p) {
  const count = Math.max(1, Number(p.repeatCount) || 1);
  const total = (Number(p.diamonds) || 0) * count;
  const img = giftImageOf(p);
  const giftIcon = img ? `<img class="gift-ic" src="${esc(img)}">` : '🎁';
  return `${avatar(p)}<div><span class="name">${esc(p.nickname)}</span><span class="text">envió ${esc(p.giftName)} x${count}</span></div>${giftIcon}<span class="badge">🪙 ${fmt(total)}</span>`;
}

function upsertGiftFeedRow(p, trackKey) {
  const feed = $('gifts');
  if (!feed) return;
  feed.querySelector('.feed-empty')?.remove();
  feed.querySelector('.empty')?.remove();
  let row = trackKey ? activeGiftFeedRows.get(trackKey) : null;
  if (row && !row.isConnected) {
    activeGiftFeedRows.delete(trackKey);
    row = null;
  }
  if (row) {
    row.innerHTML = giftFeedRowHtml(p);
  } else {
    row = document.createElement('div');
    row.className = 'row gift';
    row.innerHTML = giftFeedRowHtml(p);
    if (trackKey) {
      row.dataset.giftKey = trackKey;
      activeGiftFeedRows.set(trackKey, row);
    }
    feed.appendChild(row);
    trimFeedRows(feed);
  }
  feed.scrollTop = feed.scrollHeight;
  updateFeedCount('gifts');
}

function addGift(p) {
  if (!p) return;
  const count = Math.max(1, Number(p.repeatCount) || 1);
  const sig = `${p.uniqueId || p.userId || ''}|${p.giftId || p.giftName || ''}|${count}|${p.repeatEnd ? 1 : 0}|${p.streak ? 1 : 0}`;
  const now = Date.now();
  // Evita duplicados exactos (mismo evento llegado 2 veces)
  if (sig === lastGiftFeedSig && now - lastGiftFeedAt < 600) return;
  lastGiftFeedSig = sig;
  lastGiftFeedAt = now;

  // Racha TikTok: una sola fila que se actualiza al total (x131 → x132), no una línea por tick
  if (p.streakGift) {
    const key = `${p.uniqueId || p.userId || p.nickname || ''}::${p.giftId || p.giftName || ''}`;
    upsertGiftFeedRow(p, key);
    if (p.repeatEnd || !p.streak) activeGiftFeedRows.delete(key);
    return;
  }
  upsertGiftFeedRow(p, '');
}
function addEvent(text, cls) { pushRow('events', `<span class="text">${esc(text)}</span>`, `evt ${cls}`); }

function esc(s) {
  return String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

/* ====================== Conexión TikTok ====================== */
function desktopRelayOn() {
  return IS_DESKTOP && !!(window.desktopAPI && window.desktopAPI.relayMode);
}

async function relayConnectHttp(username) {
  const r = await fetch('/api/desktop/connect-live', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ username }),
  });
  const d = await r.json().catch(() => ({}));
  if (!r.ok) throw new Error(d.error || 'No se pudo conectar');
  return d;
}

async function relayDisconnectHttp() {
  const r = await fetch('/api/desktop/disconnect-live', { method: 'POST' });
  const d = await r.json().catch(() => ({}));
  if (!r.ok) throw new Error(d.error || 'No se pudo desconectar');
  return d;
}

async function refreshCloudSession() {
  try {
    let r = await fetch('/api/desktop/refresh-cloud-session', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: '{}',
    });
    if (r.status === 404) r = await fetch('/api/me');
    if (!r.ok) return false;
    const d = await r.json();
    const prev = window.CLOUD_ROOM_KEY || '';
    window.CLOUD_ROOM_KEY = d.cloudRoomKey || '';
    window.CLOUD_SESSION_OK = d.cloudSessionOk !== false;
    if (window.CLOUD_ROOM_KEY && window.CLOUD_ROOM_KEY !== prev) {
      connectWS();
      if (typeof refreshOverlayUrls === 'function') refreshOverlayUrls();
    }
    return !!window.CLOUD_ROOM_KEY;
  } catch {
    return false;
  }
}

let cloudSessionPollTimer = null;
function startCloudSessionPoll() {
  if (!(relayActive() || desktopRelayOn())) return;
  if (cloudSessionPollTimer) return;
  cloudSessionPollTimer = setInterval(() => { refreshCloudSession().catch(() => {}); }, 45000);
}

let connectBusy = false;

async function doConnect() {
  const u = $('username').value.trim().replace(/^@/, '');
  if (!u) { $('username').focus(); return; }
  if (connectBusy) return;
  connectBusy = true;
  const btnC = $('btnConnect');
  const markConnecting = () => {
    if (!btnC) return;
    btnC.hidden = false;
    btnC.disabled = true;
    btnC.textContent = 'Conectando…';
    btnC.classList.add('is-connecting');
    const btnD = $('btnDisconnect');
    if (btnD) btnD.hidden = true;
  };
  const resetConnectBtn = () => {
    if (!btnC) return;
    btnC.disabled = false;
    btnC.textContent = 'Conectar';
    btnC.classList.remove('is-connecting');
  };
  markConnecting();
  try {
    try { setLastTikTokUserPref(u); } catch {}

    const relay = relayActive() || desktopRelayOn();

    if (relay && !window.CLOUD_ROOM_KEY) {
      await refreshCloudSession();
    }

    if (relay && !window.CLOUD_ROOM_KEY) {
      if (!window.CLOUD_SESSION_OK) {
        toast('Sin sesión con la nube. Cierra sesión y vuelve a entrar con internet.', 'warn');
        resetConnectBtn();
        return;
      }
      try {
        await relayConnectHttp(u);
        toast('Conectando a @' + u + '…', 'ok');
      } catch (e) {
        toast(e.message || 'Sin sesión con la nube. Cierra sesión y vuelve a entrar.', 'warn');
        resetConnectBtn();
      }
      return;
    }

    if (ws?.readyState === 1) {
      send({ action: 'connect', username: u });
      return;
    }

    connectWS();
    const ok = await waitForWsOpen(relay ? 12000 : 8000);
    if (ok) {
      send({ action: 'connect', username: u });
      return;
    }
    if (relay) {
      if (!window.CLOUD_SESSION_OK) {
        toast('Sin sesión con la nube. Cierra sesión y vuelve a entrar con internet.', 'warn');
        resetConnectBtn();
        return;
      }
      try {
        await relayConnectHttp(u);
        toast('Conectando a @' + u + '…', 'ok');
        return;
      } catch (e) {
        toast(e.message || 'Render no responde. Espera 1 min y vuelve a intentar.', 'warn');
        resetConnectBtn();
        return;
      }
    }

    toast('Sin conexión al servidor. Si usas Render, espera que despierte (~1 min) y recarga.', 'warn');
    resetConnectBtn();
  } finally {
    connectBusy = false;
  }
}
async function doDisconnect() {
  if (ws?.readyState === 1) {
    send({ action: 'disconnect' });
    return;
  }
  if (desktopRelayOn()) {
    try {
      await relayDisconnectHttp();
      toast('Desconectado', 'ok');
    } catch (e) {
      toast(e.message || 'No se pudo desconectar', 'warn');
    }
    return;
  }
  send({ action: 'disconnect' });
}
$('btnConnect').onclick = doConnect;
$('btnDisconnect').onclick = doDisconnect;
$('username').addEventListener('keydown', (e) => { if (e.key === 'Enter') doConnect(); });
$('username').addEventListener('input', () => updateConnectAvatar({ username: $('username').value.trim() }));
// El prerelleno de @TikTok va por cuenta Livecoins (tras loadMe → mountUserChip).
// No usar una clave global: mezclaría el usuario TikTok entre cuentas del .exe.
$('clearChat').onclick = () => {
  const chat = $('chat');
  if (!chat) return;
  chat.innerHTML = FEED_EMPTY_HTML.chat;
  updateFeedCount('chat');
};

/* ====================== Opciones de reproducción ====================== */
if ($('opt-queue')) $('opt-queue').addEventListener('change', () => {
  if (!settings.playback) settings.playback = {};
  settings.playback.playQueue = $('opt-queue').checked;
  saveSettings();
});
if ($('opt-combo-once')) $('opt-combo-once').addEventListener('change', () => {
  if (!settings.playback) settings.playback = {};
  settings.playback.comboOnce = $('opt-combo-once').checked;
  saveSettings();
});

/* ====================== Temporizador ====================== */
let tmrRemaining = 0, tmrRunning = false, tmrLocalTick = null;
/** Tras Reiniciar, ignorar broadcasts con remaining>0 (el pause previo puede llegar tarde). */
let tmrHoldZeroUntil = 0;

function tmrFmt(sec) {
  const t = Math.max(0, Math.floor(sec));
  const h = Math.floor(t / 3600), m = Math.floor((t % 3600) / 60), s = t % 60;
  let str = '';
  if (h > 0) str += (h < 10 ? '0' : '') + h + ':';
  str += (m < 10 ? '0' : '') + m + ':' + (s < 10 ? '0' : '') + s;
  return str;
}
function tmrPaint() {
  const d = $('tmr-display');
  if (d) d.textContent = tmrFmt(tmrRemaining);
  const st = $('tmr-state');
  if (st) {
    st.textContent = tmrRunning ? 'En marcha' : (tmrRemaining <= 0 ? 'En 00:00' : 'En pausa');
    st.classList.toggle('running', tmrRunning);
  }
}
function tmrStopLocal() { if (tmrLocalTick) { clearInterval(tmrLocalTick); tmrLocalTick = null; } }
function tmrStartLocal() {
  tmrStopLocal();
  if (!tmrRunning) return;
  tmrLocalTick = setInterval(() => {
    if (tmrRemaining > 0) {
      tmrRemaining -= 1;
      if (tmrRemaining <= 0) {
        tmrRemaining = 0;
        tmrRunning = false;
        tmrStopLocal();
      }
      tmrPaint();
    }
  }, 1000);
}
function renderTimerState(p) {
  if (!p) return;
  if (Date.now() < tmrHoldZeroUntil && typeof p.remaining === 'number' && p.remaining > 0) {
    return; // stale tras Reiniciar
  }
  if (typeof p.remaining === 'number') {
    tmrRemaining = p.remaining;
    if (p.remaining === 0) tmrHoldZeroUntil = 0;
  }
  tmrRunning = !!p.running;
  tmrPaint();
  tmrStartLocal();
}
function tmrSend(op, extra) { send({ action: 'timerControl', op, ...(extra || {}) }); }

(function setupTimerControls() {
  const tmrReadFijarSec = () => {
    const min = Math.max(0, Math.floor(Number($('tmr-min')?.value) || 0));
    const sec = Math.max(0, Math.min(59, Math.floor(Number($('tmr-sec')?.value) || 0)));
    return min * 60 + sec;
  };
  const setBtn = $('tmr-setbtn');
  if (setBtn) setBtn.onclick = () => {
    tmrSend('set', { totalSeconds: tmrReadFijarSec() });
  };
  // Iniciar = SIEMPRE poner el tiempo de Fijar y arrancar (no reanudar el anterior).
  if ($('tmr-start')) $('tmr-start').onclick = () => {
    const total = tmrReadFijarSec();
    if (total <= 0) {
      try { toast('Pon minutos/segundos en Fijar para iniciar', 'err'); } catch {}
      return;
    }
    tmrHoldZeroUntil = 0;
    tmrSend('set', { totalSeconds: total });
    tmrSend('start', { totalSeconds: total });
  };
  if ($('tmr-pause')) $('tmr-pause').onclick = () => tmrSend('pause');
  // Despausar = continuar SIN tocar el tiempo (start sin totalSeconds).
  if ($('tmr-resume')) $('tmr-resume').onclick = () => {
    if (tmrRunning) return;
    if (tmrRemaining <= 0) {
      try { toast('No hay tiempo para despausar (está en 0)', 'err'); } catch {}
      return;
    }
    tmrSend('start');
  };
  // Reiniciar → 0. Id propio (tmr-ctrl-reset): "tmr-reset" es del overlay Top rotatorio.
  if ($('tmr-ctrl-reset')) $('tmr-ctrl-reset').onclick = () => {
    tmrStopLocal();
    tmrRemaining = 0;
    tmrRunning = false;
    tmrPaint();
    tmrHoldZeroUntil = Date.now() + 1500;
    // set(0) primero (autoritativo); pause después. Evita que un pause con tiempo viejo pise el 0.
    tmrSend('set', { totalSeconds: 0 });
    tmrSend('pause');
    tmrSend('reset');
  };
  document.querySelectorAll('#view-timer .tmr-quick .chip').forEach((b) => {
    b.onclick = () => {
      tmrHoldZeroUntil = 0;
      tmrSend('add', { delta: Number(b.dataset.add) || 0 });
    };
  });

  const TMR_SKINS = [
    { id: 'classic', name: 'Clásico' },
    { id: 'neon', name: 'Neón' },
    { id: 'minimal', name: 'Minimal' },
    { id: 'arcade', name: 'Arcade' },
    { id: 'glass', name: 'Glass' },
  ];
  function tmrSkinIndex(id) {
    const i = TMR_SKINS.findIndex((s) => s.id === id);
    return i >= 0 ? i : 0;
  }
  function tmrRefreshSkinPreview(skinId, opts) {
    const skin = TMR_SKINS[tmrSkinIndex(skinId)] || TMR_SKINS[0];
    if ($('tmr-skin-name')) $('tmr-skin-name').textContent = skin.name;
    if ($('tmr-skin-idx')) $('tmr-skin-idx').textContent = `${tmrSkinIndex(skin.id) + 1} / ${TMR_SKINS.length}`;
    const fr = $('tmr-ov-preview');
    if (!fr) return;
    const qs = new URLSearchParams(location.search);
    qs.set('embed', '1');
    qs.set('skin', skin.id);
    const path = `/timer.html?${qs.toString()}`;
    fr.dataset.src = path;
    const forceReload = !!(opts && opts.reload);
    const cur = String(fr.getAttribute('src') || '');
    const needsLoad = forceReload || !cur || cur === 'about:blank';
    const pushState = () => {
      try {
        fr.contentWindow.postMessage({
          type: 'livecoinsTimerSkin',
          skin: skin.id,
          remaining: tmrRemaining,
          running: tmrRunning,
        }, location.origin);
      } catch {
        try {
          fr.contentWindow.postMessage({
            type: 'livecoinsTimerSkin',
            skin: skin.id,
            remaining: tmrRemaining,
            running: tmrRunning,
          }, '*');
        } catch {}
      }
    };
    if (needsLoad) {
      fr.dataset.embedReady = '0';
      fr.addEventListener('load', () => {
        fr.dataset.embedReady = '1';
        pushState();
      }, { once: true });
      try { fr.src = path; } catch {}
      return;
    }
    // Sin recargar: cambia skin y reenvía el tiempo actual (evita flash a 00:00).
    pushState();
  }
  function tmrSetSkin(skinId) {
    if (!settings.timer) settings.timer = {};
    const skin = TMR_SKINS[tmrSkinIndex(skinId)].id;
    settings.timer.skin = skin;
    tmrRefreshSkinPreview(skin);
    // Solo el skin: no reenviar todo timer (savedRemaining viejo del cliente puede ir a 0).
    send({ action: 'saveSettings', settings: { timer: { skin } }, ...profileSaveMeta() });
  }
  function tmrStepSkin(dir) {
    const cur = tmrSkinIndex(settings.timer?.skin || 'classic');
    const next = (cur + dir + TMR_SKINS.length) % TMR_SKINS.length;
    tmrSetSkin(TMR_SKINS[next].id);
  }
  if ($('tmr-skin-prev')) $('tmr-skin-prev').onclick = () => tmrStepSkin(-1);
  if ($('tmr-skin-next')) $('tmr-skin-next').onclick = () => tmrStepSkin(1);
  try { tmrRefreshSkinPreview(settings.timer?.skin || 'classic'); } catch {}
  window.__tmrRefreshSkinPreview = tmrRefreshSkinPreview;

  // Ajustes (reglas + opciones): se guardan al cambiar.
  const bindNum = (id, key) => {
    const el = $(id);
    if (!el) return;
    el.addEventListener('change', () => {
      if (!settings.timer) settings.timer = {};
      settings.timer[key] = Number(el.value) || 0;
      saveSettings();
    });
  };
  bindNum('tmr-giftmult', 'giftMult');
  bindNum('tmr-like', 'like');
  bindNum('tmr-follow', 'follow');
  bindNum('tmr-share', 'share');
  bindNum('tmr-subscribe', 'subscribe');
  bindNum('tmr-superfan', 'superFan');
  bindNum('tmr-chat', 'chat');
  bindNum('tmr-penalty-secs', 'penaltySecs');

  function refreshTimerPenaltyLabel() {
    const t = settings.timer || {};
    const btn = $('tmr-penalty-pick');
    const idEl = $('tmr-penalty-giftid');
    const nameEl = $('tmr-penalty-giftname');
    if (idEl) idEl.value = t.penaltyGiftId ? String(t.penaltyGiftId) : '';
    if (nameEl) nameEl.value = t.penaltyGiftName ? String(t.penaltyGiftName) : '';
    if (!btn) return;
    const id = t.penaltyGiftId ? String(t.penaltyGiftId) : '';
    const name = t.penaltyGiftName ? String(t.penaltyGiftName) : '';
    if (!id && !name) {
      btn.innerHTML = '🎁 Elegir regalo…';
      btn.title = 'Elegir regalo';
      return;
    }
    let img = t.penaltyGiftImage ? String(t.penaltyGiftImage) : '';
    try {
      if (!img && id && typeof giftCatalogById !== 'undefined') {
        img = giftCatalogById.get(id)?.image || '';
      }
      if (!img && name && typeof giftCatalog !== 'undefined') {
        img = giftCatalog.find((x) => String(x.name || '').toLowerCase() === name.toLowerCase())?.image || '';
      }
    } catch {}
    const tip = name || ('#' + id);
    if (img) {
      btn.innerHTML = `<img class="gift-pick-ic" src="${esc(img)}" alt="" onerror="this.outerHTML='🎁'">`;
    } else {
      btn.innerHTML = '🎁';
    }
    btn.title = tip;
  }

  if ($('tmr-penalty-pick')) {
    $('tmr-penalty-pick').onclick = () => {
      try {
        openGiftModalCb((g) => {
          if (!settings.timer) settings.timer = {};
          settings.timer.penaltyGiftId = String(g.id || '');
          settings.timer.penaltyGiftName = String(g.name || '');
          settings.timer.penaltyGiftImage = String(g.image || '');
          refreshTimerPenaltyLabel();
          saveSettings();
        });
      } catch (err) {
        try { toast('No se pudo abrir el catálogo de regalos', 'err'); } catch {}
      }
    };
  }
  if ($('tmr-penalty-clear')) {
    $('tmr-penalty-clear').onclick = () => {
      if (!settings.timer) settings.timer = {};
      settings.timer.penaltyGiftId = '';
      settings.timer.penaltyGiftName = '';
      settings.timer.penaltyGiftImage = '';
      refreshTimerPenaltyLabel();
      saveSettings();
    };
  }

  // Tope / al llegar a 00:00. El tiempo vivo NO se toca desde aquí (solo Reiniciar → 0).
  if ($('tmr-maxcap')) $('tmr-maxcap').addEventListener('change', () => {
    if (!settings.timer) settings.timer = {};
    settings.timer.maxCapSec = Math.max(0, Math.round((Number($('tmr-maxcap').value) || 0) * 60));
    saveSettings();
  });
  if ($('tmr-maxon')) $('tmr-maxon').addEventListener('change', () => {
    if (!settings.timer) settings.timer = {};
    settings.timer.maxEnabled = $('tmr-maxon').checked;
    saveSettings();
  });
  if ($('tmr-onfinish')) $('tmr-onfinish').addEventListener('change', () => {
    if (!settings.timer) settings.timer = {};
    settings.timer.actionOnFinish = $('tmr-onfinish').value;
    saveSettings();
  });
})();

function applyTimerSettingsUI() {
  const t = settings.timer || {};
  const setVal = (id, v) => { const el = $(id); if (el) el.value = v; };
  setVal('tmr-giftmult', t.giftMult ?? 5);
  setVal('tmr-like', t.like ?? 2);
  setVal('tmr-follow', t.follow ?? 10);
  setVal('tmr-share', t.share ?? 15);
  setVal('tmr-subscribe', t.subscribe ?? 60);
  setVal('tmr-superfan', t.superFan ?? 60);
  setVal('tmr-chat', t.chat ?? 0);
  setVal('tmr-penalty-secs', t.penaltySecs ?? 30);
  setVal('tmr-maxcap', Math.round((t.maxCapSec ?? 18000) / 60));
  if ($('tmr-maxon')) $('tmr-maxon').checked = !!t.maxEnabled;
  if ($('tmr-onfinish')) {
    const act = t.actionOnFinish || 'pause';
    $('tmr-onfinish').value = act === 'reset' ? 'pause' : act;
  }
  try {
    if (typeof window.__tmrRefreshSkinPreview === 'function') {
      window.__tmrRefreshSkinPreview(t.skin || 'classic');
    }
  } catch {}
  if ($('tmr-penalty-giftid')) $('tmr-penalty-giftid').value = t.penaltyGiftId ? String(t.penaltyGiftId) : '';
  if ($('tmr-penalty-giftname')) $('tmr-penalty-giftname').value = t.penaltyGiftName ? String(t.penaltyGiftName) : '';
  try {
    const pickBtn = $('tmr-penalty-pick');
    if (pickBtn) {
      const id = t.penaltyGiftId ? String(t.penaltyGiftId) : '';
      const name = t.penaltyGiftName ? String(t.penaltyGiftName) : '';
      if (!id && !name) {
        pickBtn.innerHTML = '🎁 Elegir regalo…';
        pickBtn.title = 'Elegir regalo';
      } else {
        let img = t.penaltyGiftImage ? String(t.penaltyGiftImage) : '';
        try {
          if (!img && id && giftCatalogById) img = giftCatalogById.get(id)?.image || '';
        } catch {}
        const tip = name || ('#' + id);
        pickBtn.innerHTML = img
          ? `<img class="gift-pick-ic" src="${esc(img)}" alt="" onerror="this.outerHTML='🎁'">`
          : '🎁';
        pickBtn.title = tip;
      }
    }
  } catch {}
}

/* ====================== Ajustes (sync con servidor) ====================== */
let saveDebounce = null;
let settingsKeysSaveDebounce = null;
const settingsKeysSavePending = new Set();
let settingsKeysSkipErSync = false;
/** Evita que un save (toggle Activa / boot apagar acciones) reconstruya Editor Pro. */
let erSyncSuppressedUntil = 0;
function suppressEditorRapidoSync(ms = 1500) {
  erSyncSuppressedUntil = Math.max(erSyncSuppressedUntil, Date.now() + Math.max(0, ms));
}
/** Cancela guardados pendientes para que un perfil no contamine otro al cambiar. */
function cancelPendingProfileSaves() {
  clearTimeout(saveDebounce);
  saveDebounce = null;
  clearTimeout(settingsKeysSaveDebounce);
  settingsKeysSaveDebounce = null;
  settingsKeysSavePending.clear();
  settingsKeysSkipErSync = false;
}
function profileSaveMeta() {
  const editingGeneral = !!(profilesState && profilesState.editingGeneral);
  return {
    profileActive: editingGeneral ? null : (profilesState && Number.isInteger(profilesState.active) ? profilesState.active : null),
    editMode: editingGeneral ? 'general' : 'profile',
    settingsGeneration: profilesState && profilesState.settingsGeneration != null
      ? Number(profilesState.settingsGeneration)
      : null,
  };
}
function saveSettings() {
  if (applyingSettings) return;
  try { window.__lcPendingTouchedKeys = null; } catch {}
  clearTimeout(saveDebounce);
  saveDebounce = setTimeout(() => {
    stripSettingsMediaForSave(settings);
    send({ action: 'saveSettings', settings, ...profileSaveMeta() });
    if (typeof syncWinsHotkeysToDesktop === 'function') syncWinsHotkeysToDesktop();
    scheduleErSyncFromLinkedGame();
  }, 200);
}

function scheduleErSyncFromLinkedGame() {
  try {
    if (Date.now() < erSyncSuppressedUntil) return;
    let key = '';
    if (typeof window.getEditorRapidoLinkedSettingsKey === 'function') {
      key = window.getEditorRapidoLinkedSettingsKey() || '';
    }
    if (!key) {
      const raw = JSON.parse(localStorage.getItem('livecoins_editor_rapido_v10') || 'null');
      key = String(raw?.gameSync?.settingsKey || '').trim();
    }
    if (key && Array.isArray(settings?.[key])) notifyEditorRapidoActionsChanged(key);
  } catch {}
}

// Al abrir la app, cada lista de acciones de juego arranca apagada una sola vez.
// El flag de sesión evita volver a apagarla cuando llega un eco de settings o
// después de que el usuario la enciende manualmente.
function bootGameActionsOffOnce(flag, getList, renderFn) {
  if (typeof renderFn !== 'function') return;
  if (!window[flag]) {
    window[flag] = true;
    const list = typeof getList === 'function' ? getList() : [];
    let changed = false;
    for (const action of (Array.isArray(list) ? list : [])) {
      if (!action || action.enabled === false) continue;
      action.enabled = false;
      changed = true;
    }
    // Las llamadas consecutivas se consolidan; flush ya: UI OFF no debe spawnear en el live.
    if (changed) {
      suppressEditorRapidoSync(2500);
      flushSaveSettings();
    }
  }
  renderFn();
}
function sendTestMcActionTimed(uid, findFn) {
  const a = findFn ? findFn(uid) : null;
  if (!a) { sendTestMcAction(uid); return; }
  runTimedGameActionTest(a, () => sendTestMcAction(uid), { timingMode: 'repeat' });
}
function sendTestMcAction(uid) {
  flushSaveSettings();
  if (IS_DESKTOP) {
    fetch('/api/desktop/mc-test', {
      method: 'POST',
      credentials: 'same-origin',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ uid, settings }),
    }).then((r) => r.json().catch(() => ({}))).then((d) => {
      toast && toast(d.ok ? 'Comando enviado al servidor local.' : (d.error || 'Error MC'), d.ok ? 'ok' : 'warn');
    }).catch(() => {
      toast && toast('No se pudo probar Minecraft localmente.', 'warn');
    });
    return;
  }
  if (ws?.readyState !== WebSocket.OPEN) {
    toast && toast('Sin conexión al servidor. Espera a que el panel conecte.', 'warn');
    return;
  }
  send({ action: 'testMcAction', uid });
  toast && toast('Enviando comando al servidor de Minecraft…', 'ok');
}
function flushSaveSettings() {
  if (applyingSettings || !settings) return;
  clearTimeout(saveDebounce);
  saveDebounce = null;
  stripSettingsMediaForSave(settings);
  send({ action: 'saveSettings', settings, ...profileSaveMeta() });
}

/** En relay el panel guarda en la nube; el webhook :3199 lee la room local.
 *  Empuja videos/batallas/acciones al servidor local al instante (sin recargar). */
function syncDesktopWebhookSettings() {
  if (!IS_DESKTOP || !settings) return Promise.resolve(false);
  const patch = {
    videos: settings.videos || [],
    videosEnabled: settings.videosEnabled !== false,
    battleAlerts: settings.battleAlerts || [],
    battleAlertsEnabled: settings.battleAlertsEnabled !== false,
    soundAlerts: settings.soundAlerts || [],
    actions: settings.actions || [],
    mcActions: settings.mcActions || [],
  };
  return fetch('/api/desktop/sync-webhook-media', {
    method: 'POST',
    credentials: 'same-origin',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(patch),
  }).then((r) => r.ok).catch(() => false);
}

function mcCmdReady(a) {
  return !!(a && a.enabled !== false && (a.cmd || (Array.isArray(a.cmds) && a.cmds.length)));
}

function onSettings(s, touchedKeys) {
  if (!touchedKeys || !touchedKeys.length) {
    try {
      if (Array.isArray(window.__lcPendingTouchedKeys) && window.__lcPendingTouchedKeys.length
        && Date.now() - (window.__lcPendingTouchedAt || 0) < 2000) {
        touchedKeys = window.__lcPendingTouchedKeys;
      }
    } catch {}
  }
  try { window.__lcPendingTouchedKeys = null; } catch {}
  settings = preserveLocalWinsOnSettingsEcho(preserveLocalTopKillsOnSettingsEcho(preserveLocalGameActionsOnSettingsEcho(s)));
  if (migrateAccionesSpawnWebhooks(settings.actions)) saveSettings();
  normalizeRelayMedia(settings);
  ['toplikesRank', 'topdiamRank', 'toplikesList', 'topdiamList', 'top1fire', 'habibiTop', 'topGift', 'lastGift', 'topStreak'].forEach((k) => {
    if (settings[k] && settings[k].resetPeriod == null) settings[k].resetPeriod = 'live';
  });
  if (settings.topAltRank) {
    if (settings.topAltRank.resetPeriodLikes == null) settings.topAltRank.resetPeriodLikes = 'live';
    if (settings.topAltRank.resetPeriodDiam == null) settings.topAltRank.resetPeriodDiam = 'live';
  }
  if (settings.topAltRankNeon) {
    if (settings.topAltRankNeon.resetPeriodLikes == null) settings.topAltRankNeon.resetPeriodLikes = 'live';
    if (settings.topAltRankNeon.resetPeriodDiam == null) settings.topAltRankNeon.resetPeriodDiam = 'live';
  }
  if (settings.topMultiRank) {
    if (settings.topMultiRank.resetPeriodLikes == null) settings.topMultiRank.resetPeriodLikes = 'live';
    if (settings.topMultiRank.resetPeriodDiam == null) settings.topMultiRank.resetPeriodDiam = 'live';
    if (settings.topMultiRank.resetPeriodComments == null) settings.topMultiRank.resetPeriodComments = 'live';
    if (settings.topMultiRank.showLikes == null) settings.topMultiRank.showLikes = true;
    if (settings.topMultiRank.showCoins == null) settings.topMultiRank.showCoins = true;
    if (settings.topMultiRank.showComments == null) settings.topMultiRank.showComments = true;
    if (settings.topMultiRank.showPoints == null) settings.topMultiRank.showPoints = true;
  }
  scheduleSettingsUiApply(touchedKeys);
}

/** Coalesce ecos de settings: varios patches seguidos → un solo repaint. */
let settingsUiCoalesceTimer = null;
let settingsUiPendingFull = false;
let settingsUiPendingKeys = null; // Set | null (null + !full = still empty)

function scheduleSettingsUiApply(touchedKeys) {
  const keys = Array.isArray(touchedKeys) && touchedKeys.length ? touchedKeys : null;
  if (!keys) {
    settingsUiPendingFull = true;
    settingsUiPendingKeys = null;
  } else if (!settingsUiPendingFull) {
    if (!settingsUiPendingKeys) settingsUiPendingKeys = new Set();
    for (const k of keys) settingsUiPendingKeys.add(k);
  }
  clearTimeout(settingsUiCoalesceTimer);
  settingsUiCoalesceTimer = setTimeout(flushSettingsUiApply, 80);
}

function flushSettingsUiApply() {
  settingsUiCoalesceTimer = null;
  const full = settingsUiPendingFull || !settingsUiPendingKeys || !settingsUiPendingKeys.size;
  const touched = full ? null : [...settingsUiPendingKeys];
  settingsUiPendingFull = false;
  settingsUiPendingKeys = null;

  applyingSettings = true;
  try {
    applySettingsToUI(touched);
  } finally {
    applyingSettings = false;
  }

  try { if (typeof window.refreshScreenFxUi === 'function' && (!touched || touched.includes('screenFx'))) window.refreshScreenFxUi(); } catch {}
  try {
    if (!touched || touched.includes('tiktokPhoto') || touched.includes('tiktokUser')) {
      const livePhoto = String(settings?.tiktokPhoto || '').trim();
      if (livePhoto) {
        updateDockUserAvatar({
          photo: livePhoto,
          nickname: settings.tiktokUser || '',
          username: window.MY_USER,
        });
      }
    }
  } catch {}

  if (full || (touched && (touched.includes('spotify') || touched.includes('music')))) {
    if (typeof onMusicSettingsLoaded === 'function') onMusicSettingsLoaded();
  }
  if (full) {
    applyLimitUI();
    renderPlanView();
    // Al abrir el panel, las acciones de juego arrancan apagadas (una sola vez por sesión).
    bootGameActionsOffOnce('_rbxResetDone', ensureRobloxSlots, renderRobloxActions);
    bootGameActionsOffOnce('_rbx3ResetDone', ensureRoblox3Slots, renderRoblox3Actions);
    bootGameActionsOffOnce('_marioResetDone', ensureMarioActions, renderMarioActions);
    bootGameActionsOffOnce('_pvzResetDone', ensurePvzActions, renderPvzActions);
    bootGameActionsOffOnce('_smb3ResetDone', ensureSmb3Actions, renderSmb3Actions);
    bootGameActionsOffOnce('_mari0ResetDone', ensureMari0Actions, renderMari0Actions);
    bootGameActionsOffOnce('_pvzHybridResetDone', ensurePvzHybridActions, renderPvzHybridActions);
    bootGameActionsOffOnce('_repoResetDone', ensureRepoActions, renderRepoActions);
    bootGameActionsOffOnce('_l4dResetDone', ensureL4dActions, renderL4dActions);
    bootGameActionsOffOnce('_unturnedResetDone', ensureUnturnedActions, renderUnturnedActions);
    bootGameActionsOffOnce('_gtavkothResetDone', ensureGtavKothActions, renderGtavKothActions);
    bootGameActionsOffOnce('_gtavchaosResetDone', ensureGtavChaosActions, renderGtavChaosActions);
    bootGameActionsOffOnce('_gtavchiliadResetDone', ensureGtavChiliadActions, renderGtavChiliadActions);
    bootGameActionsOffOnce('_ctrResetDone', ensureCtrActions, renderCtrActions);
    bootGameActionsOffOnce('_mslugResetDone', ensureMslugActions, renderMslugActions);
    bootGameActionsOffOnce('_smwResetDone', ensureSmwActions, renderSmwActions);
    bootGameActionsOffOnce('_gdashResetDone', ensureGdashActions, renderGdashActions);
    bootGameActionsOffOnce('_mcResetDone', () => settings?.mcActions || [], renderMyMcActions);
    bootGameActionsOffOnce('_mcshooterResetDone', () => settings?.mcshooterActions || [], renderMyMcShooterActions);
    applyMcShooterColiseoUI();
    bootGameActionsOffOnce('_bedrockResetDone', () => settings?.bedrockActions || [], renderMyBedrockActions);
    bootGameActionsOffOnce('_mcparkourResetDone', () => settings?.parkourActions || [], renderMyParkourActions);
    bootGameActionsOffOnce('_mckothResetDone', () => settings?.kothActions || [], renderMyKothActions);
    bootGameActionsOffOnce('_mcfarmResetDone', () => settings?.farmActions || [], renderMyFarmActions);
    bootGameActionsOffOnce('_sandboxResetDone', () => settings?.sandboxActions || [], renderMySandboxActions);
  } else if (touched) {
    refreshGameActionsUiForKeys(touched);
  }
}

