function entityMatchesSearch(obj, q, extraKeys = []) {
  if (!q) return true;
  const keys = ['name', 'giftName', 'giftId', 'soundName', 'trigger', 'event', 'keys', 'command', ...extraKeys];
  const hay = keys.map((k) => String(obj?.[k] || '')).join(' ').toLowerCase();
  return hay.includes(q);
}

/** Empty state con guía en 1 línea (Conecta → Probar → …). Solo UI. */
function lcEmptyGuideHTML(opts = {}) {
  const title = opts.title || 'Aún no hay nada aquí';
  const steps = Array.isArray(opts.steps) ? opts.steps.filter(Boolean) : [];
  const hint = opts.hint || '';
  const extraClass = opts.className || 'empty';
  const stepsHtml = steps.length
    ? `<p class="lc-empty-steps">${steps.map((s, i) => (
        (i ? '<span class="lc-empty-sep" aria-hidden="true">→</span>' : '') +
        `<span class="lc-empty-step">${esc(String(s))}</span>`
      )).join('')}</p>`
    : '';
  const hintHtml = hint ? `<p class="lc-empty-hint">${hint}</p>` : '';
  return `<div class="lc-empty ${extraClass}">
    <div class="lc-empty-tt">${title}</div>
    ${stepsHtml}
    ${hintHtml}
  </div>`;
}
function giftTriggerVisualFromItem(item, fallbackEmoji = '🎁') {
  if (!item) return { img: '', emoji: fallbackEmoji, label: 'Evento' };
  if (item.image) return { img: item.image, emoji: fallbackEmoji, label: item.name || 'Custom' };
  const giftId = item.giftId;
  const giftName = item.giftName;
  if (giftId || giftName) {
    const g = giftId
      ? giftCatalogById.get(String(giftId))
      : giftCatalog.find((x) => x.name.toLowerCase() === String(giftName).toLowerCase());
    return {
      img: g?.image || item.giftImage || '',
      emoji: '🎁',
      label: giftName || g?.name || 'Regalo',
    };
  }
  const trig = item.trigger || item.event || '';
  if (trig === 'emote' || item.emoteId) {
    const img = item.emoteImage || emoteImgById(item.emoteId);
    return { img: img || '', emoji: '😀', label: item.emoteId || 'Sticker' };
  }
  const emoji = (typeof EVENT_EMOJI !== 'undefined' && EVENT_EMOJI[trig]) || fallbackEmoji;
  let label = trig;
  try {
    if (typeof triggerLabel === 'function') label = triggerLabel(item);
    else if (typeof baTriggerLabel === 'function' && String(trig).startsWith('battle')) label = baTriggerLabel(item);
  } catch {}
  return { img: '', emoji, label: label || 'Evento' };
}

function bindSaCardLongPressReorder(container, onReorder) {
  if (!container || typeof onReorder !== 'function') return;
  container._saOnReorder = onReorder;
  if (container.dataset.saReorder === '1') return;
  container.dataset.saReorder = '1';

  const HOLD_MS = 420;
  const CANCEL_PX = 12;
  const INTERACTIVE = 'button, input, select, textarea, a, label, .toggle, .sa-card-btns, .acc-card-icons, .vid-card-btns, .sa-vol, .vid-card-vol';

  container.addEventListener('pointerdown', (e) => {
    if (e.button != null && e.button !== 0) return;
    const card = e.target.closest?.('.sa-card');
    if (!card || !container.contains(card) || !card.dataset.id) return;
    if (e.target.closest?.(INTERACTIVE)) return;

    const pointerId = e.pointerId;
    const startX = e.clientX;
    const startY = e.clientY;
    let timer = null;
    let dragging = false;
    let moved = false;

    const finish = () => {
      if (timer) { clearTimeout(timer); timer = null; }
      window.removeEventListener('pointermove', onMove);
      window.removeEventListener('pointerup', onUp);
      window.removeEventListener('pointercancel', onUp);
      if (dragging) {
        try { card.releasePointerCapture?.(pointerId); } catch {}
        card.classList.remove('sa-dragging');
        container.classList.remove('sa-reordering');
        if (moved) {
          const ids = [...container.querySelectorAll('.sa-card')].map((c) => c.dataset.id).filter(Boolean);
          try { container._saOnReorder?.(ids); } catch {}
          const swallow = (ev) => {
            ev.preventDefault();
            ev.stopPropagation();
            card.removeEventListener('click', swallow, true);
          };
          card.addEventListener('click', swallow, true);
          setTimeout(() => card.removeEventListener('click', swallow, true), 400);
        }
      }
    };

    const onMove = (ev) => {
      if (ev.pointerId !== pointerId) return;
      const dx = ev.clientX - startX;
      const dy = ev.clientY - startY;
      if (!dragging) {
        if (Math.hypot(dx, dy) > CANCEL_PX && timer) {
          clearTimeout(timer);
          timer = null;
        }
        return;
      }
      ev.preventDefault();
      const under = document.elementFromPoint(ev.clientX, ev.clientY);
      const over = under?.closest?.('.sa-card');
      if (!over || over === card || !container.contains(over)) return;
      const rect = over.getBoundingClientRect();
      const before = ev.clientY < rect.top + rect.height / 2;
      const ref = before ? over : over.nextSibling;
      if (ref === card || (before && card.nextSibling === over) || (!before && over.nextSibling === card)) return;
      container.insertBefore(card, ref);
      moved = true;
    };

    const onUp = (ev) => {
      if (ev.pointerId !== pointerId) return;
      finish();
    };

    timer = setTimeout(() => {
      timer = null;
      dragging = true;
      card.classList.add('sa-dragging');
      container.classList.add('sa-reordering');
      try { card.setPointerCapture(pointerId); } catch {}
    }, HOLD_MS);

    window.addEventListener('pointermove', onMove, { passive: false });
    window.addEventListener('pointerup', onUp);
    window.addEventListener('pointercancel', onUp);
  });
}

/* Guardar SOLO las claves pedidas (no todo settings).
   Evita que encender/apagar reenvíe rankings y vacíe likes/gifts.
   Último arg opcional: { skipErSync: true, flush: true } — no toca Editor Pro (toggle Activa). */
function saveSettingsKeysPatch(...keysAndOpts) {
  if (applyingSettings) return;
  let opts = {};
  const keys = [];
  for (const k of keysAndOpts) {
    if (k && typeof k === 'object' && !Array.isArray(k) && ('skipErSync' in k || 'erSync' in k)) {
      opts = k;
    } else if (typeof k === 'string' && k) {
      keys.push(k);
    }
  }
  for (const k of keys) {
    settingsKeysSavePending.add(k);
  }
  if (opts.skipErSync) {
    settingsKeysSkipErSync = true;
    suppressEditorRapidoSync(1500);
  }
  clearTimeout(settingsKeysSaveDebounce);
  const runPatch = () => {
    settingsKeysSaveDebounce = null;
    if (!settings || !settingsKeysSavePending.size) return;
    const skipEr = settingsKeysSkipErSync;
    settingsKeysSkipErSync = false;
    const patch = {};
    const touched = [...settingsKeysSavePending];
    for (const k of settingsKeysSavePending) {
      if (k === 'videos') {
        patch.videos = settings.videos || [];
        patch.videosEnabled = settings.videosEnabled !== false;
      } else if (k === 'battleAlerts') {
        patch.battleAlerts = settings.battleAlerts || [];
        patch.battleAlertsEnabled = settings.battleAlertsEnabled !== false;
      } else if (Object.prototype.hasOwnProperty.call(settings, k) || settings[k] != null) {
        patch[k] = settings[k];
      }
    }
    settingsKeysSavePending.clear();
    if (!Object.keys(patch).length) return;
    try {
      window.__lcPendingTouchedKeys = touched.slice();
      window.__lcPendingTouchedAt = Date.now();
    } catch {}
    send({ action: 'saveSettings', settings: patch, ...profileSaveMeta() });
    if (!skipEr) {
      for (const k of touched) {
        if (ER_SYNCABLE_ACTION_KEYS.includes(k)) notifyEditorRapidoActionsChanged(k);
      }
    }
  };
  if (opts.flush) {
    runPatch();
    return;
  }
  settingsKeysSaveDebounce = setTimeout(runPatch, 200);
}
/** Envía ya el patch de claves pendientes (Activa OFF no debe esperar 200ms). */
function flushSaveSettingsKeysPatch() {
  if (applyingSettings || !settings || !settingsKeysSavePending.size) {
    clearTimeout(settingsKeysSaveDebounce);
    settingsKeysSaveDebounce = null;
    return;
  }
  clearTimeout(settingsKeysSaveDebounce);
  settingsKeysSaveDebounce = null;
  saveSettingsKeysPatch(...[...settingsKeysSavePending], {
    skipErSync: settingsKeysSkipErSync,
    flush: true,
  });
}
function saveVideosBattlePatch(kind) {
  saveSettingsKeysPatch(kind);
  syncDesktopWebhookSettings();
}

