/* ----- Selector de regalos ----- */
let giftCatalog = [];
const giftCatalogById = new Map();
let communityGiftCatalog = [];

function indexGiftCatalog() {
  giftCatalogById.clear();
  giftCatalogSorted = null;
  for (const g of giftCatalog) giftCatalogById.set(String(g.id), g);
}

/** Lista ordenada cacheada (evita sort O(n log n) en cada tecla / apertura). */
let giftCatalogSorted = null;
function getSortedGiftCatalog() {
  if (giftCatalogSorted) return giftCatalogSorted;
  giftCatalogSorted = [...giftCatalog].sort((a, b) =>
    (Number(a.diamonds) || 0) - (Number(b.diamonds) || 0) || String(a.name || '').localeCompare(String(b.name || ''))
  );
  return giftCatalogSorted;
}

function mergeGiftCatalogWithCommunity(base, community) {
  const byId = new Map();
  for (const g of [...(community || []), ...(base || [])]) {
    const id = String(g?.id ?? '');
    if (!id) continue;
    byId.set(id, { ...byId.get(id), ...g });
  }
  return [...byId.values()].sort((a, b) =>
    (Number(a.diamonds) || 0) - (Number(b.diamonds) || 0) || String(a.name || '').localeCompare(String(b.name || ''))
  );
}

let giftCatalogLoading = false;
async function preloadGiftCatalog(attempt = 0) {
  if (giftCatalog.length) return;
  if (giftCatalogLoading) return;
  giftCatalogLoading = true;
  try {
    const res = await fetch('/api/gifts');
    const data = await res.json();
    giftCatalog = data.results || [];
    indexGiftCatalog();
    giftCatalogLoading = false;
    // Una vez cargado el catálogo, volvemos a dibujar TODAS las secciones que muestran
    // iconos de regalo, por si sus fichas se dibujaron antes (entonces salía el emoji).
    if (giftCatalog.length) refreshGiftCards();
  } catch {
    giftCatalogLoading = false;
    // Reintenta: la primera carga puede fallar si el servidor está "despertando" o la
    // red parpadea. Así las fichas SIEMPRE terminan mostrando el regalo configurado.
    if (attempt < 6) setTimeout(() => preloadGiftCatalog(attempt + 1), 2000);
  }
}

// Re-dibuja las secciones con iconos de regalo (cuando ya hay catálogo y ajustes).
function refreshGiftCards() {
  if (!settings) return;
  if (typeof renderSoundAlerts === 'function') { try { renderSoundAlerts(); } catch {} }
  if (typeof renderVideos === 'function') { try { renderVideos(); } catch {} }
  if (typeof renderBattleAlerts === 'function') { try { renderBattleAlerts(); } catch {} }
  if (typeof renderAcciones === 'function') { try { renderAcciones(); } catch {} }
  if (typeof pushGiftShowcasePreview === 'function') { try { pushGiftShowcasePreview(settings?.giftShowcase); } catch {} }
  if (typeof pushGiftGoalsPreview === 'function') { try { pushGiftGoalsPreview(settings?.giftGoals); } catch {} }
  if (typeof syncGgmScaleUi === 'function') {
    try { syncGgmScaleUi(settings?.giftGoals?.scale || 100); } catch {}
  }
}

const EVENT_EMOJI = {
  like: '❤️', likeGlobal: '❤️', follow: '➕', share: '🔁',
  subscribe: '⭐', superFan: '🌟', superFanJoin: '🌟', levelUp: '⬆️', emote: '😀', gift: '🎁',
  chatCommand: '💬', firstMessage: '🙋', streamdeck: '🎛️',
};
const TRIG_ICON = {
  'gift-any': '/img/trig/diamonds.png?v=2',
  gift: '/img/trig/gift.png?v=2',
  'gift-name': '/img/trig/gift.png?v=2',
  'gift-diamonds': '/img/trig/diamonds.png?v=2',
  like: '/img/trig/like.png?v=2',
  likeGlobal: '/img/trig/like-global.png?v=2',
  share: '/img/trig/share.png?v=2',
  subscribe: '/img/trig/subscribe.png?v=2',
  superFan: '/img/trig/superfan.png?v=2',
  superFanJoin: '/img/trig/superfan-join.png?v=2',
  follow: '/img/trig/follow.png?v=2',
  levelUp: '/img/trig/levelup.png?v=2',
  emote: '/img/trig/emote.png?v=2',
  chatCommand: '/img/trig/chat.png?v=2',
  chatUser: '/img/trig/chat.png?v=2',
  firstMessage: '/img/trig/firstmsg.png?v=2',
  streamdeck: '/img/trig/streamdeck.png?v=2',
};
function trigIconChip(key) {
  const src = TRIG_ICON[key];
  if (!src) return null;
  return `<span class="acc-chip-ico"><img class="acc-chip-trig" src="${src}" alt=""></span>`;
}
function trigIconImg(key, cls = 'sa-ic-img') {
  const src = TRIG_ICON[key];
  if (!src) return '';
  return `<img class="${cls}" src="${src}" alt="" loading="lazy" decoding="async">`;
}
/** Icono HTML para disparadores de juegos (MC / Mario / SFX…). gift-any = regalo, no diamantes. */
function gameTrigIconHtml(key, cls = 'mc-trig-img') {
  let src = TRIG_ICON[key];
  if (key === 'gift-any') src = '/img/trig/gift.png?v=2';
  if (!src) return `<span class="mc-trig-emoji">⚡</span>`;
  return `<img class="${cls}" src="${src}" alt="" loading="lazy" decoding="async">`;
}
/** Precarga iconos de disparadores en idle para que modales abran al instante. */
(function prefetchTrigIcons() {
  const run = () => {
    try {
      const seen = new Set();
      Object.values(TRIG_ICON).forEach((src) => {
        if (!src || seen.has(src)) return;
        seen.add(src);
        const img = new Image();
        img.decoding = 'async';
        img.src = src;
      });
    } catch {}
  };
  if (typeof requestIdleCallback === 'function') requestIdleCallback(run, { timeout: 2000 });
  else setTimeout(run, 800);
})();

// Busca la imagen de un sticker/emote por su id en el catálogo cargado.
function emoteImgById(id) {
  if (!id) return '';
  const e = emoteCatalog.find((x) => String(x.id) === String(id));
  return e?.image || '';
}

// Devuelve el HTML del icono de la alerta (regalo real, sticker, imagen propia o emoji)
function alertIconHTML(a) {
  if (a.image) return `<img class="sa-ic-img" src="${esc(a.image)}" loading="lazy" decoding="async">`;
  const trig = a.trigger || 'gift';
  if (trig === 'gift' && a.giftId) {
    const g = giftCatalogById.get(String(a.giftId));
    if (g?.image) return `<img class="sa-ic-img" src="${esc(g.image)}" loading="lazy" decoding="async">`;
  }
  if (trig === 'gift' && a.giftName) {
    const g = giftCatalog.find((x) => x.name.toLowerCase() === a.giftName.toLowerCase());
    if (g?.image) return `<img class="sa-ic-img" src="${esc(g.image)}" loading="lazy" decoding="async">`;
  }
  if (trig === 'emote') {
    const img = a.emoteImage || emoteImgById(a.emoteId);
    if (img) return `<img class="sa-ic-img" src="${esc(img)}" loading="lazy" decoding="async">`;
  }
  const trigImg = trigIconImg(trig === 'gift' && (a.rangeMin || a.rangeMax) ? 'gift-any' : trig, 'sa-ic-img');
  if (trigImg) return trigImg;
  return `<span class="sa-ic-emoji">${EVENT_EMOJI[trig] || '🔔'}</span>`;
}

// Versión pequeña para la esquina de las tarjetas
function alertIconSmall(a) {
  const trig = a.trigger || 'gift';
  let img = '';
  if (a.image) img = a.image;
  else if (trig === 'gift' && a.giftId) img = giftCatalogById.get(String(a.giftId))?.image || '';
  else if (trig === 'gift' && a.giftName) img = giftCatalog.find((x) => x.name.toLowerCase() === a.giftName.toLowerCase())?.image || '';
  else if (trig === 'emote') img = a.emoteImage || emoteImgById(a.emoteId);
  if (img) return `<img class="sa-ic-mini" src="${esc(img)}" loading="lazy" decoding="async">`;
  const trigImg = trigIconImg(trig === 'gift' && (a.rangeMin || a.rangeMax) ? 'gift-any' : trig, 'sa-ic-mini');
  if (trigImg) return trigImg;
  return `<span class="sa-ic-mini-emoji">${EVENT_EMOJI[trig] || '🔔'}</span>`;
}

/* ----- Selector de stickers / emotes (compartido sa/vid) ----- */
let emoteCatalog = [];
let emoteTarget = 'vid';

function updateEmotePickBtn(target) {
  const t = target || emoteTarget;
  const btn = $(t + '-emotepick');
  if (!btn) return;
  const id = $(t + '-emoteid').value;
  const e = emoteCatalog.find((x) => String(x.id) === String(id));
  if (id && e?.image) btn.innerHTML = `<img class="sa-ic-mini" src="${esc(e.image)}"> Sticker elegido`;
  else if (id) btn.textContent = `🙂 Sticker #${id}`;
  else btn.textContent = '🙂 Elegir sticker…';
}

async function openEmoteModal(target = 'vid') {
  emoteTarget = target;
  const modal = $('emoteModal');
  if (!modal) return;
  try {
    if (modal.parentElement !== document.body) document.body.appendChild(modal);
  } catch {}
  modal.classList.remove('hidden');
  const grid = $('emote-grid');
  if (grid) grid.innerHTML = '<div class="empty">Cargando…</div>';
  // Si ya hay stickers en alertas/videos importados, súbelos al catálogo antes de pintar.
  try { seedEmoteCatalogFromImport(collectEmotesFromLivecoinsSettings(settings)); } catch {}
  const cached = emoteCatalog.slice();
  try {
    // En modo relay la conexión TikTok vive en Render: pedir catálogo a la nube.
    const apiUrl = (relayActive() || desktopRelayOn()) ? '/api/desktop/emotes' : '/api/emotes';
    const res = await fetch(apiUrl);
    const data = await res.json();
    const fresh = data.results || [];
    seedEmoteCatalogFromImport([...(fresh || []), ...cached]);
  } catch {
    emoteCatalog = cached;
  }
  renderEmoteGrid();
}
function closeEmoteModal() { $('emoteModal').classList.add('hidden'); }

function renderEmoteGrid() {
  const grid = $('emote-grid');
  if (!grid) return;
  if (!emoteCatalog.length) {
    grid.innerHTML = '<div class="empty">Aún no aparecen stickers.<br>Importa un .tfc de TikFinity o espera a que alguien use un sticker en tu live.</div>';
    return;
  }
  const curId = $(emoteTarget + '-emoteid').value;
  grid.innerHTML = emoteCatalog.map((e) => {
    const label = esc(e.name || (`#${String(e.id).slice(-6)}`));
    const thumb = e.image
      ? `<img src="${esc(e.image)}" loading="lazy" onerror="this.outerHTML='<div class=\\'emote-ph\\'>🙂</div>'">`
      : `<div class="emote-ph">🙂</div>`;
    return `
    <div class="gift-cell ${String(e.id) === curId ? 'sel' : ''}" data-id="${esc(e.id)}" title="${esc(e.name || '')} #${esc(e.id)}">
      ${thumb}
      <div class="g-name">${label}</div>
    </div>`;
  }).join('');
  grid.querySelectorAll('.gift-cell').forEach((cell) => {
    cell.onclick = () => {
      $(emoteTarget + '-emoteid').value = cell.dataset.id;
      updateEmotePickBtn(emoteTarget);
      closeEmoteModal();
    };
  });
}

/** Stickers con trigger emote ya guardados en settings. */
function collectEmotesFromLivecoinsSettings(s) {
  const map = new Map();
  const add = (id, image, name) => {
    const eid = String(id || '').trim();
    if (!eid) return;
    const prev = map.get(eid) || { id: eid, image: '', name: '' };
    map.set(eid, {
      id: eid,
      image: prev.image || String(image || '').trim(),
      name: prev.name || String(name || '').trim(),
    });
  };
  for (const a of s?.soundAlerts || []) {
    if (a?.trigger === 'emote' && a.emoteId) add(a.emoteId, a.emoteImage, a.name);
  }
  for (const v of s?.videos || []) {
    if (v?.trigger === 'emote' && v.emoteId) add(v.emoteId, v.emoteImage, v.name);
  }
  for (const a of s?.actions || []) {
    if (a?.trigger === 'emote' && a.emoteId) add(a.emoteId, a.emoteImage, a.name);
  }
  return [...map.values()];
}

/** Une stickers al catálogo local y pide al servidor persistirlos. */
function seedEmoteCatalogFromImport(list) {
  if (!Array.isArray(list) || !list.length) return 0;
  const map = new Map(emoteCatalog.map((e) => [String(e.id), { ...e }]));
  let added = 0;
  for (const e of list) {
    const id = String(e?.id || e?.emoteId || '').trim();
    if (!id) continue;
    const img = String(e.image || e.emoteImage || '').trim();
    const name = String(e.name || e.nombre || '').trim();
    const prev = map.get(id);
    if (!prev) {
      map.set(id, { id, image: img, name });
      added += 1;
    } else {
      map.set(id, {
        id,
        image: prev.image || img,
        name: prev.name || name,
      });
    }
  }
  emoteCatalog = [...map.values()];
  try { send({ action: 'importEmotes', emotes: emoteCatalog }); } catch {}
  return added;
}

// Contenido del botón "Elegir regalo": muestra el icono real del regalo (no el emoji)
// cuando hay uno seleccionado. Se usa en alertas, videos y acciones.
function giftBtnHTML(name, id, fallback = '🎁 Elegir regalo…') {
  if (!name && !id) return fallback;
  const g = id ? giftCatalogById.get(String(id))
    : giftCatalog.find((x) => x.name.toLowerCase() === String(name).toLowerCase());
  const label = name || g?.name || '';
  const icon = g?.image ? `<img class="gift-pick-ic" src="${esc(g.image)}" onerror="this.outerHTML='🎁'">` : '🎁';
  return `${icon} ${esc(label)}`;
}

function updateGiftPickBtn() {
  $('sa-giftpick').innerHTML = giftBtnHTML($('sa-gift').value, $('sa-giftid').value);
}

function updateGiftPickBtnV() {
  $('vid-giftpick').innerHTML = giftBtnHTML($('vid-gift').value, $('vid-giftid').value);
}

let giftTarget = 'sa'; // 'sa' (sonido) o 'vid' (video)
let giftPickCallback = null; // si se define, recibe el regalo elegido en vez de rellenar inputs

$('sa-giftpick').onclick = () => openGiftModal('sa');
$('vid-giftpick').onclick = () => openGiftModal('vid');
$('vid-emotepick').onclick = () => openEmoteModal('vid');
$('sa-emotepick').onclick = () => openEmoteModal('sa');
$('emote-close').onclick = closeEmoteModal;
$('emoteModal').addEventListener('click', (e) => { if (e.target.id === 'emoteModal') closeEmoteModal(); });
$('gift-close').onclick = () => $('giftModal').classList.add('hidden');
$('giftModal').addEventListener('click', (e) => { if (e.target.id === 'giftModal') $('giftModal').classList.add('hidden'); });
let giftFilterTimer = null;
$('gift-q').addEventListener('input', () => {
  clearTimeout(giftFilterTimer);
  giftFilterTimer = setTimeout(() => renderGiftGrid($('gift-q').value.trim()), 120);
});

const GIFT_MUSIC_NAME_RE = /music|song|melody|mic|guitar|piano|dj|beat|concert|album|drum|karaoke|band|singer|violin|trumpet|spotify|nota|canci[oó]n/i;
let giftModalTab = 'all';
function isMusicGift(g) {
  return !!(g && (g.audio || GIFT_MUSIC_NAME_RE.test(String(g.name || ''))));
}
if ($('gift-tabs')) {
  $('gift-tabs').addEventListener('click', (e) => {
    const btn = e.target.closest('.gift-tab');
    if (!btn) return;
    giftModalTab = btn.dataset.tab || 'all';
    $('gift-tabs').querySelectorAll('.gift-tab').forEach((el) => el.classList.toggle('active', el === btn));
    renderGiftGrid($('gift-q').value.trim());
  });
}

const GIFT_GRID_PAGE = 72;
let giftGridList = [];
let giftGridShown = 0;
let giftCommunityFetchedAt = 0;
let giftCommunityMerged = false;

function ensureGiftGridBindings(grid) {
  if (!grid || grid._giftBound) return;
  grid._giftBound = true;
  grid.addEventListener('click', (e) => {
    const cell = e.target.closest('.gift-cell');
    if (!cell || !grid.contains(cell)) return;
    pickGiftCell(cell);
  });
  grid.addEventListener('scroll', () => {
    if (giftGridShown >= giftGridList.length) return;
    if (grid.scrollTop + grid.clientHeight < grid.scrollHeight - 180) return;
    appendGiftGridPage();
  }, { passive: true });
}

function pickGiftCell(cell) {
  if (giftPickCallback) {
    const g = giftCatalogById.get(String(cell.dataset.id));
    giftPickCallback({
      id: cell.dataset.id,
      name: g?.name || cell.dataset.name || '',
      image: g?.image || '',
      diamonds: g?.diamonds || 0,
    });
    giftPickCallback = null;
    $('giftModal').classList.add('hidden');
    return;
  }
  $(giftTarget + '-gift').value = cell.dataset.name;
  $(giftTarget + '-giftid').value = cell.dataset.id;
  if (giftTarget === 'vid') updateGiftPickBtnV(); else updateGiftPickBtn();
  $('giftModal').classList.add('hidden');
}

function giftCellHtml(g, curId) {
  return `<div class="gift-cell ${String(g.id) === curId ? 'sel' : ''}" data-id="${g.id}" data-name="${esc(g.name)}" title="${esc(g.name)} · #${g.id}">
      ${isMusicGift(g) ? '<span class="g-audio" title="Música / Audio">🎵</span>' : ''}
      <img src="${esc(g.image)}" loading="lazy" decoding="async" onerror="this.style.visibility='hidden'">
      <div class="g-name">${esc(g.name)}</div>
      <div class="g-coin">🪙 ${g.diamonds}</div>
    </div>`;
}

function appendGiftGridPage() {
  const grid = $('gift-grid');
  if (!grid || giftGridShown >= giftGridList.length) return;
  const curId = giftPickCallback ? '' : ($(giftTarget + '-giftid')?.value || '');
  const slice = giftGridList.slice(giftGridShown, giftGridShown + GIFT_GRID_PAGE);
  giftGridShown += slice.length;
  grid.insertAdjacentHTML('beforeend', slice.map((g) => giftCellHtml(g, curId)).join(''));
}

async function openGiftModalCb(cb) {
  await openGiftModal('sa', cb);
}

async function openGiftModal(target = 'sa', cb = null) {
  giftPickCallback = cb;
  giftTarget = target;
  giftModalTab = 'all';
  const modal = $('giftModal');
  if (!modal) return;
  /* El HTML vive dentro de una .view; si esa pestaña no está activa (display:none),
     el modal no se ve. Sacarlo a body al abrir. */
  try {
    if (modal.parentElement !== document.body) document.body.appendChild(modal);
  } catch {}
  if ($('gift-tabs')) {
    $('gift-tabs').querySelectorAll('.gift-tab').forEach((el) => el.classList.toggle('active', el.dataset.tab === 'all'));
  }
  modal.classList.remove('hidden');
  if ($('gift-q')) $('gift-q').value = '';
  // Mostrar al instante si el catálogo ya está en memoria (preload / apertura previa).
  if (giftCatalog.length) {
    if (communityGiftCatalog.length && !giftCommunityMerged) {
      giftCatalog = mergeGiftCatalogWithCommunity(giftCatalog, communityGiftCatalog);
      giftCommunityMerged = true;
      indexGiftCatalog();
    }
    renderGiftGrid('');
  } else {
    if ($('gift-grid')) $('gift-grid').innerHTML = '<div class="empty">Cargando regalos…</div>';
  }

  // Actualiza en segundo plano; no bloquea el click del selector.
  void (async () => {
  try {
    const communityUrl = (relayActive() || desktopRelayOn()) ? '/api/desktop/community-gifts' : '/api/community-gifts';
    const needsGifts = !giftCatalog.length;
    const needsCommunity = (Date.now() - giftCommunityFetchedAt) > 120000;
    if (!needsGifts && !needsCommunity) return;
    const [giftsRes, communityRes] = await Promise.all([
      needsGifts ? fetch('/api/gifts') : Promise.resolve(null),
      needsCommunity ? fetch(communityUrl).catch(() => null) : Promise.resolve(null),
    ]);
    let changed = false;
    const prevLen = giftCatalog.length;
    if (giftsRes) {
      const data = await giftsRes.json();
      giftCatalog = data.results || giftCatalog;
      giftCommunityMerged = false;
      changed = true;
    }
    if (communityRes?.ok) {
      const commData = await communityRes.json();
      communityGiftCatalog = commData.results || [];
      giftCommunityFetchedAt = Date.now();
      if (communityGiftCatalog.length) {
        giftCatalog = mergeGiftCatalogWithCommunity(giftCatalog, communityGiftCatalog);
        giftCommunityMerged = true;
        changed = true;
      }
    } else if (needsCommunity) {
      giftCommunityFetchedAt = Date.now();
    }
    if (changed) {
      indexGiftCatalog();
      if (giftCatalog.length !== prevLen || needsGifts) {
        if (!$('giftModal').classList.contains('hidden')) renderGiftGrid($('gift-q').value.trim());
      }
    }
  } catch {
    if (!giftCatalog.length) {
      $('gift-grid').innerHTML = '<div class="empty">No se pudo cargar el catálogo (¿hay internet?)</div>';
    }
  }
  })();
}

function renderGiftGrid(filter) {
  const grid = $('gift-grid');
  if (!grid) return;
  ensureGiftGridBindings(grid);
  const f = (filter || '').toLowerCase();
  const sorted = getSortedGiftCatalog();
  let list = f
    ? sorted.filter((g) =>
      String(g.name || '').toLowerCase().includes(f)
      || String(g.id).includes(f)
      || String(g.diamonds).includes(f))
    : sorted;
  if (giftModalTab === 'music') list = list.filter(isMusicGift);
  if (!list.length) {
    giftGridList = [];
    giftGridShown = 0;
    grid.innerHTML = giftModalTab === 'music'
      ? '<div class="empty">No hay regalos de música/audio en el catálogo</div>'
      : '<div class="empty">Sin resultados</div>';
    return;
  }
  giftGridList = list;
  giftGridShown = 0;
  grid.innerHTML = '';
  appendGiftGridPage();
}

/* Subir propio */
$('sa-upbtn').onclick = () => $('sa-soundfile').click();
$('sa-soundfile').addEventListener('change', (e) => uploadFile(e.target.files[0], 'sound'));

async function uploadFile(file, kind) {
  if (!file) return;
  const label = $('sa-soundname');
  label.textContent = 'Subiendo…';
  try {
    const res = await fetch('/api/upload?name=' + encodeURIComponent(file.name), { method: 'POST', body: file });
    const data = await res.json();
    if (!data.url) throw new Error(data.error || 'error');
    pendingSound = { url: data.url, name: file.name }; label.textContent = file.name;
  } catch (err) {
    label.textContent = uploadErrLabel(err);
  }
}

/* Biblioteca de sonidos: lee la carpeta local /audios */
let libAudio = null;
let localSounds = [];
// A dónde va el sonido elegido: 'alert', 'action' o 'mc' (tarjeta Minecraft).
let soundPickTarget = 'alert';
let mcSoundPickUid = null;
let mcAudioUploadUid = null;

function openSoundLib() {
  $('soundLibModal').classList.remove('hidden');
  const pcBtn = $('sa-lib-frompc');
  if (pcBtn) pcBtn.hidden = soundPickTarget !== 'mc';
  loadLocalSounds();
}
function closeSoundLib() {
  $('soundLibModal').classList.add('hidden');
  try { libAudio?.pause(); } catch {}
}
$('sa-libbtn').onclick = () => { soundPickTarget = 'alert'; openSoundLib(); };
$('lib-close').onclick = closeSoundLib;
if ($('sa-lib-frompc')) {
  $('sa-lib-frompc').onclick = () => {
    if (soundPickTarget !== 'mc' || !mcSoundPickUid) return;
    mcAudioUploadUid = mcSoundPickUid;
    ensureMcAudioUpload().click();
  };
}
$('soundLibModal').addEventListener('click', (e) => { if (e.target.id === 'soundLibModal') closeSoundLib(); });
$('sa-librefresh').onclick = () => loadLocalSounds();
$('sa-libq').addEventListener('input', () => renderLocalSounds($('sa-libq').value.trim()));

async function loadLocalSounds() {
  const box = $('sa-libresults');
  box.innerHTML = '<div class="empty">Cargando…</div>';
  try {
    const res = await fetch('/api/local-sounds');
    const data = await res.json();
    localSounds = data.results || [];
    renderLocalSounds($('sa-libq').value.trim());
  } catch {
    box.innerHTML = '<div class="empty">No se pudo leer la carpeta «audios»</div>';
  }
}

function renderLocalSounds(filter) {
  const box = $('sa-libresults');
  const f = (filter || '').toLowerCase();
  const list = f ? localSounds.filter((s) => s.name.toLowerCase().includes(f)) : localSounds;
  if (!list.length) {
    box.innerHTML = localSounds.length
      ? '<div class="empty">Ningún audio coincide</div>'
      : '<div class="empty">No hay audios en la carpeta «audios».<br>Copia tus .mp3 ahí y pulsa ↻</div>';
    return;
  }
  box.innerHTML = list.map((s) => `
    <div class="lib-row">
      <span class="lr-name">${esc(s.name)}</span>
      <button type="button" class="lr-play acc-icon-btn acc-try-delay" data-url="${esc(s.url)}" title="Escuchar" aria-label="Escuchar">
        <svg class="acc-ico" viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M8 5v14l11-7z"/></svg>
      </button>
      <button type="button" class="lr-pick" data-url="${esc(s.url)}" data-name="${esc(s.name)}">Usar</button>
    </div>`).join('');
  box.querySelectorAll('.lr-play').forEach((b) => b.onclick = () => {
    try { libAudio?.pause(); } catch {}
    libAudio = new Audio(b.dataset.url); libAudio.play().catch(() => {});
  });
  box.querySelectorAll('.lr-pick').forEach((b) => b.onclick = () => {
    if (soundPickTarget === 'action') {
      accPendingSound = { url: b.dataset.url, name: b.dataset.name };
      const el = $('acc-soundname'); if (el) el.textContent = b.dataset.name;
      const vr = $('acc-volrow'); if (vr) vr.hidden = false;
    } else if (soundPickTarget === 'mc' && mcSoundPickUid) {
      const hit = findAnyGameAction(mcSoundPickUid) || findMcFamilyAction(mcSoundPickUid);
      if (hit?.action) {
        hit.action.sound = b.dataset.url;
        hit.action.soundName = b.dataset.name;
        hit.action.audioOn = true;
        if (hit.action.soundVolume == null) hit.action.soundVolume = 100;
        flushSaveSettings();
        if (typeof hit.render === 'function') hit.render();
      }
    } else {
      pendingSound = { url: b.dataset.url, name: b.dataset.name };
      $('sa-soundname').textContent = b.dataset.name;
    }
    closeSoundLib();
  });
}

$('sa-save').onclick = async () => {
  const name = $('sa-name').value.trim();
  if (!name) { $('sa-status').textContent = '⚠️ Escribe un nombre.'; return; }
  if (!pendingSound?.url) { $('sa-status').textContent = '⚠️ Elige un sonido (biblioteca o subir propio).'; return; }

  const ev = $('sa-event').value;
  const id = ensureSaEditId();
  const data = {
    name,
    trigger: ev === 'gift-any' || ev === 'gift-name' ? 'gift' : ev,
    giftName: ev === 'gift-name' ? $('sa-gift').value.trim() : '',
    giftId: ev === 'gift-name' ? ($('sa-giftid').value || '') : '',
    minDiamonds: ev === 'gift-name' ? (+$('sa-mindia').value || 0) : 0,
    rangeMin: ev === 'gift-any' ? (+$('sa-rangemin').value || 0) : 0,
    rangeMax: ev === 'gift-any' ? (+$('sa-rangemax').value || 0) : 0,
    likeMin: ev === 'like' ? Math.max(1, +$('sa-likemin').value || 1) : 0,
    likeGoal: ev === 'likeGlobal' ? Math.max(1, +$('sa-likegoal').value || 100) : 0,
    emoteId: ev === 'emote' ? $('sa-emoteid').value.trim() : '',
    emoteImage: ev === 'emote' ? emoteImgById($('sa-emoteid').value.trim()) : '',
    eventDelay: (ev === 'follow' || ev === 'share' || ev === 'emote') ? Math.max(0, parseInt($('sa-eventdelay').value, 10) || 0) : 0,
    sound: pendingSound.url,
    soundName: pendingSound.name || 'audio',
    image: '',
    volume: +$('sa-vol').value,
    enabled: $('sa-active').checked,
  };
  if (!settings.soundAlerts) settings.soundAlerts = [];
  const existing = settings.soundAlerts.find((x) => x.id === id);
  if (existing) Object.assign(existing, data);
  else settings.soundAlerts.push({ id, ...data });
  editingId = id;
  flushSaveSettings();
  await syncDesktopWebhookSettings();
  renderSoundAlerts();
  closeSaModal();
  if (ev === 'streamdeck') {
    toast && toast('Guardado. Usa 🔗 en la tarjeta para copiar el webhook a Stream Deck.', 'ok');
  }
};

$('sa-delsel').onclick = async () => {
  if (!selected.size) return;
  const ok = await askConfirm({ title: 'Borrar seleccionadas', message: `Se eliminarán ${selected.size} alerta(s) sonora(s).` });
  if (!ok) return;
  settings.soundAlerts = settings.soundAlerts.filter((a) => !selected.has(a.id));
  selected.clear();
  saveSettings();
  renderSoundAlerts();
};

