/* ====================== Tarjetas PRO: Jarrón y Vaquita ====================== */
const DEFAULT_JAR_SIZES = [
  { t: 5000, sz: 88 }, { t: 1000, sz: 70 }, { t: 100, sz: 56 }, { t: 30, sz: 40 }, { t: 0, sz: 32 },
];

// Configuración de cada overlay tipo "bote" (mismo comportamiento, distinta tarjeta)
const POT_OVERLAYS = {
  perrito: { previewId: 'perr-preview', testAction: 'testPerrito', resetAction: 'resetPerrito', dropAction: 'dropPerrito',
             btnTest: 'perr-test', btnReset: 'perr-reset', btnConfig: 'perr-config', btnSimGift: 'perr-simgift', btnDrop1: 'perr-drop1', copyBtnIdx: 0 },
  jarron: { previewId: 'jar-preview', testAction: 'testJarron', resetAction: 'resetJarron', dropAction: 'dropJarron',
            btnTest: 'jar-test', btnReset: 'jar-reset', btnConfig: 'jar-config', btnSimGift: 'jar-simgift', btnDrop1: 'jar-drop1', copyBtnIdx: 0 },
  vaquita: { previewId: 'vaq-preview', testAction: 'testVaquita', resetAction: 'resetVaquita', dropAction: 'dropVaquita',
             btnTest: 'vaq-test', btnReset: 'vaq-reset', btnConfig: 'vaq-config', btnSimGift: 'vaq-simgift', btnDrop1: 'vaq-drop1', copyBtnIdx: 1 },
  marranito: { previewId: 'mar-preview', testAction: 'testMarranito', resetAction: 'resetMarranito', dropAction: 'dropMarranito',
               btnTest: 'mar-test', btnReset: 'mar-reset', btnConfig: 'mar-config', btnSimGift: 'mar-simgift', btnDrop1: 'mar-drop1', copyBtnIdx: 2 },
  corazonLava: { previewId: 'ghl-preview', testAction: 'testCorazonLava', resetAction: 'resetCorazonLava', dropAction: 'dropCorazonLava',
                 btnTest: 'ghl-test', btnReset: 'ghl-reset', btnConfig: 'ghl-config', btnSimGift: 'ghl-simgift', btnDrop1: 'ghl-drop1', copyBtnIdx: 3 },
};

const potSimGift = { perrito: null, jarron: null, vaquita: null, marranito: null, corazonLava: null };

function renderPotSimGiftBtn(key) {
  const cfg = POT_OVERLAYS[key]; if (!cfg) return;
  const btn = $(cfg.btnSimGift); if (!btn) return;
  const g = potSimGift[key];
  if (!g) {
    btn.innerHTML = 'Selecciona…';
    btn.title = 'Elegir regalo para soltar de uno en uno';
    return;
  }
  const img = g.image ? `<img src="${String(g.image).replace(/"/g, '&quot;')}" alt="" referrerpolicy="no-referrer">` : '🎁';
  const name = String(g.name || 'Regalo').replace(/</g, '&lt;');
  btn.innerHTML = `${img}<span class="ovpro-simgift-name">${name}</span>`;
  btn.title = `${g.name || 'Regalo'} · ${g.diamonds || 0} coins · ID ${g.id || ''}`;
}

(function setupPotCards() {
  document.querySelectorAll('.ovpro-card').forEach((card) => {
    const code = card.querySelector('.ov-url');
    if (!code) return;
    code.textContent = roomUrl(code.dataset.path);
    card.querySelector('.ovpro-copy')?.addEventListener('click', (e) => {
      if (isOverlayUrlLocked(code)) { toast('Disponible solo en Premium ⭐', 'warn'); return; }
      navigator.clipboard?.writeText(roomUrl(code.dataset.path));
      const t = e.target; t.textContent = '¡Copiado!';
      setTimeout(() => (t.textContent = 'Copiar enlace'), 1200);
    });
  });

  for (const [key, cfg] of Object.entries(POT_OVERLAYS)) {
    const test = $(cfg.btnTest), reset = $(cfg.btnReset), config = $(cfg.btnConfig);
    if (!test) continue;
    const toPreview = (msg) => $(cfg.previewId)?.contentWindow?.postMessage({ kind: key, ...msg }, '*');
    const pushTintLook = () => {
      const tint = String(settings?.[key]?.tint ?? '').trim();
      toPreview({ type: 'config', tint: tint || '', tintRainbow: !!settings?.[key]?.tintRainbow });
    };
    const fr = $(cfg.previewId);
    if (fr && !fr.dataset.potTintLoadHook) {
      fr.dataset.potTintLoadHook = '1';
      fr.addEventListener('load', () => {
        if (!fr.getAttribute('src') || fr.getAttribute('src') === 'about:blank') return;
        // Reaplicar tinte/arcoíris tras (re)carga del iframe
        setTimeout(pushTintLook, 40);
      });
    }
    test.onclick = () => {
      if (key === 'corazonLava') {
        const c = settings?.corazonLava || {};
        const payload = {
          type: 'test',
          count: 36,
          filterGiftId: c.filterGiftId || '7934',
          filterGiftName: c.filterGiftName || 'Heart Me',
          filterGiftImage: c.filterGiftImage || '',
          filterGiftDiamonds: Number(c.filterGiftDiamonds) || 15,
          giftId: c.filterGiftId || '7934',
          giftName: c.filterGiftName || 'Heart Me',
          image: c.filterGiftImage || '',
          diamonds: Number(c.filterGiftDiamonds) || 15,
        };
        toPreview(payload);
        send({ action: cfg.testAction, count: 36, ...payload });
        return;
      }
      toPreview({ type: 'test', count: 40 });
      toPreview({ type: 'topDemo' });
      // OBS/live: menos que 200 para no tumbar la PC; la preview del panel ya va en 40
      send({ action: cfg.testAction, count: 80 });
    };
    reset.onclick = () => {
      toPreview({ type: 'reset' });
      send({ action: cfg.resetAction });
      // Reset no debe tocar el look: reafirma tinte/arcoíris por si el iframe parpadeó
      setTimeout(pushTintLook, 30);
    };
    if (config) config.onclick = () => openPotConfig(key);

    const dropPayload = () => {
      let g = potSimGift[key];
      if (key === 'corazonLava') {
        const c = settings?.corazonLava || {};
        g = g || {
          id: c.filterGiftId || '7934',
          name: c.filterGiftName || 'Heart Me',
          image: c.filterGiftImage || '',
          diamonds: Number(c.filterGiftDiamonds) || 15,
        };
      }
      return {
        image: g?.image || '',
        diamonds: Math.max(0, Number(g?.diamonds) || 1),
        giftId: g?.id != null ? String(g.id) : '',
        giftName: g?.name || '',
      };
    };
    if ($(cfg.btnSimGift)) {
      $(cfg.btnSimGift).onclick = () => {
        openGiftModalCb((g) => {
          potSimGift[key] = {
            id: g.id, name: g.name, image: g.image || '',
            diamonds: Number(g.diamonds) || Number(g.diamond_count) || 1,
          };
          renderPotSimGiftBtn(key);
        });
      };
      renderPotSimGiftBtn(key);
    }
    if ($(cfg.btnDrop1)) {
      $(cfg.btnDrop1).onclick = () => {
        const payload = dropPayload();
        toPreview({ type: 'dropOne', ...payload });
        send({ action: cfg.dropAction, ...payload });
      };
    }
  }

  // Top donador (misma tarjeta PRO, pero con su propia config)
  const topPrev = () => $('top-preview')?.contentWindow;
  const toTopPreview = (msg) => topPrev()?.postMessage({ kind: 'topdonor', ...msg }, '*');
  if ($('top-test')) {
    $('top-test').onclick = () => { toTopPreview({ type: 'test' }); send({ action: 'testTopDonor' }); };
    $('top-reset').onclick = () => { toTopPreview({ type: 'reset' }); send({ action: 'stopTopDonor' }); };
    $('top-config').onclick = openTopConfig;
  }
})();

/* ---- Modal de configuración (compartido por jarrón y vaquita) ---- */
let cfgTarget = 'jarron';
let cfgSizesDraft = [];
/** Color de relleno del <input type="color"> al quitar tinte; NO es el default del overlay (default = sin tinte). */
const POT_TINT_PICKER_PLACEHOLDER = '#7cc8ff';

function normalizeAlcanciaTintDefaults() {
  if (!settings) return false;
  let changed = false;
  for (const key of ['jarron', 'vaquita', 'marranito', 'perrito', 'corazonLava']) {
    if (!settings[key] || typeof settings[key] !== 'object') continue;
    const t = String(settings[key].tint ?? '').trim();
    if (!t) {
      if (settings[key].tint) { settings[key].tint = ''; changed = true; }
      continue;
    }
    // Perfiles que guardaron el azul del picker por el bug (tint vacío → se mostraba/guardaba #7cc8ff).
    if (t.toLowerCase() === POT_TINT_PICKER_PLACEHOLDER) {
      settings[key].tint = '';
      changed = true;
    }
  }
  // Corazón lava: regalo filtro por defecto = Heart Me
  if (settings.corazonLava && typeof settings.corazonLava === 'object') {
    const c = settings.corazonLava;
    if (!String(c.filterGiftId || '').trim() && !String(c.filterGiftName || '').trim()) {
      c.filterGiftId = '7934';
      c.filterGiftName = 'Heart Me';
      c.filterGiftImage = c.filterGiftImage || 'https://p16-webcast.tiktokcdn.com/img/maliva/webcast-va/d56945782445b0b8c8658ed44f894c7b~tplv-obj.webp';
      c.filterGiftDiamonds = Number(c.filterGiftDiamonds) || 15;
      changed = true;
    }
    potSimGift.corazonLava = {
      id: c.filterGiftId || '7934',
      name: c.filterGiftName || 'Heart Me',
      image: c.filterGiftImage || '',
      diamonds: Number(c.filterGiftDiamonds) || 15,
    };
    try { renderPotSimGiftBtn('corazonLava'); } catch {}
  }
  return changed;
}

function cfgPreviewWin() { return $(POT_OVERLAYS[cfgTarget].previewId)?.contentWindow; }
function cfgToPreview(msg) { cfgPreviewWin()?.postMessage({ kind: cfgTarget, ...msg }, '*'); }

function openPotConfig(target) {
  cfgTarget = target;
  if (!settings[target]) settings[target] = {};
  const data = settings[target];
  // tint vacío = sin tinte (default). No usar || placeholder (convertía '' en azul y al Guardar lo persistía).
  let tint = String(data.tint == null ? '' : data.tint).trim();
  if (tint.toLowerCase() === POT_TINT_PICKER_PLACEHOLDER) tint = '';
  const tintEl = $('jarcfg-tint');
  if (tintEl) {
    tintEl.value = /^#/.test(tint) ? tint : POT_TINT_PICKER_PLACEHOLDER;
    tintEl.dataset.cleared = tint ? '' : '1';
  }
  if ($('jarcfg-tintrainbow')) $('jarcfg-tintrainbow').checked = !!data.tintRainbow;
  cfgToPreview({ type: 'config', tint: tint || '', tintRainbow: !!data.tintRainbow });
  cfgSizesDraft = (data.sizes && data.sizes.length)
    ? data.sizes.map((r) => ({ t: Number(r.t) || 0, sz: Number(r.sz) || 32 }))
    : DEFAULT_JAR_SIZES.map((r) => ({ ...r }));
  const titles = {
    perrito: '🐶 Configurar — Perrito (bote regalos)',
    vaquita: '🐮 Configurar — Vaquita (bote regalos)',
    marranito: '🐷 Configurar — Marranito (bote regalos)',
    corazonLava: '❤️ Configurar — Meta Heart Me',
    jarron: '⚙️ Configurar — Jarrón (bote regalos)',
  };
  $('jarcfg-title').textContent = titles[target] || titles.jarron;
  const isHeart = target === 'corazonLava';
  const topWrap = $('jarcfg-topbar-wrap');
  if (topWrap) topWrap.style.display = isHeart ? 'none' : '';
  const metaWrap = $('jarcfg-meta-wrap');
  if (metaWrap) metaWrap.style.display = isHeart ? '' : 'none';
  if (isHeart) {
    if ($('jarcfg-meta-label')) $('jarcfg-meta-label').value = String(data.metaLabel != null ? data.metaLabel : 'Meta');
    if ($('jarcfg-meta-goal')) $('jarcfg-meta-goal').value = Math.max(1, Number(data.metaGoal) || 50);
    if ($('jarcfg-meta-mode')) $('jarcfg-meta-mode').value = data.metaMode === 'coins' ? 'coins' : 'gifts';
    const fid = String(data.filterGiftId != null ? data.filterGiftId : '7934');
    const fname = String(data.filterGiftName != null ? data.filterGiftName : 'Heart Me');
    const fimg = String(data.filterGiftImage || '');
    const fd = Math.max(1, Number(data.filterGiftDiamonds) || 15);
    if ($('jarcfg-filter-giftid')) $('jarcfg-filter-giftid').value = fid;
    if ($('jarcfg-filter-giftname')) $('jarcfg-filter-giftname').value = fname;
    if ($('jarcfg-filter-giftimage')) $('jarcfg-filter-giftimage').value = fimg;
    if ($('jarcfg-filter-giftdiamonds')) $('jarcfg-filter-giftdiamonds').value = String(fd);
    renderJarFilterGiftBtn();
    pushJarMetaPreview();
  }
  $('jarcfg-topbar-on').checked = data.topBarEnabled !== false;
  $('jarcfg-topbar-limit').value = Math.max(1, Math.min(10, Number(data.topBarLimit) || 3));
  const tbColor = data.topBarColor || '#161820';
  if ($('jarcfg-topbar-color')) $('jarcfg-topbar-color').value = /^#/.test(tbColor) ? tbColor : '#161820';
  const tbOp = Math.max(0, Math.min(100, Number(data.topBarOpacity != null ? data.topBarOpacity : 88)));
  if ($('jarcfg-topbar-opacity')) $('jarcfg-topbar-opacity').value = tbOp;
  if ($('jarcfg-topbar-op-lbl')) $('jarcfg-topbar-op-lbl').textContent = tbOp + '%';
  const toastWrap = $('jarcfg-gifttoast-wrap');
  if (toastWrap) toastWrap.style.display = '';
  if ($('jarcfg-gifttoast-on')) {
    $('jarcfg-gifttoast-on').checked = data.giftToastEnabled !== false;
  }
  const gtColor = data.giftToastColor || '#1c1e26';
  if ($('jarcfg-gifttoast-color')) $('jarcfg-gifttoast-color').value = /^#/.test(gtColor) ? gtColor : '#1c1e26';
  const gtOp = Math.max(0, Math.min(100, Number(data.giftToastOpacity != null ? data.giftToastOpacity : 90)));
  if ($('jarcfg-gifttoast-opacity')) $('jarcfg-gifttoast-opacity').value = gtOp;
  if ($('jarcfg-gifttoast-op-lbl')) $('jarcfg-gifttoast-op-lbl').textContent = gtOp + '%';
  renderJarRows();
  $('jarConfigModal').classList.remove('hidden');
  if (!isHeart) pushJarTopBarPreview();
  pushJarGiftToastPreview();
}
function closeJarConfig() { $('jarConfigModal').classList.add('hidden'); }

function renderJarRows() {
  const sorted = [...cfgSizesDraft].sort((a, b) => b.t - a.t);
  cfgSizesDraft = sorted;
  const wrap = $('jarcfg-rows');
  if (!wrap) return;
  wrap.innerHTML = sorted.map((r, i) => {
    const next = sorted[i - 1]; // umbral inmediatamente superior
    const range = next ? `${r.t} a ${next.t - 1} monedas` : `≥ ${r.t} monedas`;
    return `
      <div class="jarcfg-row" data-i="${i}">
        <button type="button" class="jarcfg-del" title="Quitar">✕</button>
        <div class="jarcfg-row-head">UMBRAL ${i + 1} <span class="rng">— ${range} · ${r.sz} px</span></div>
        <div class="jarcfg-row-grid">
          <div>
            <label>Si el regalo ≥ (monedas / diamantes)</label>
            <input type="number" min="0" class="jc-t" value="${r.t}">
          </div>
          <div>
            <label>Tamaño del icono (px)</label>
            <input type="number" min="8" max="200" class="jc-sz" value="${r.sz}">
          </div>
        </div>
      </div>`;
  }).join('');

  wrap.querySelectorAll('.jarcfg-row').forEach((row) => {
    const i = Number(row.dataset.i);
    row.querySelector('.jc-t').onchange = (e) => { cfgSizesDraft[i].t = Math.max(0, parseInt(e.target.value, 10) || 0); renderJarRows(); };
    row.querySelector('.jc-sz').onchange = (e) => { cfgSizesDraft[i].sz = Math.max(8, Math.min(200, parseInt(e.target.value, 10) || 32)); renderJarRows(); };
    row.querySelector('.jarcfg-del').onclick = () => { cfgSizesDraft.splice(i, 1); renderJarRows(); };
  });

  // Refleja los tamaños en la vista previa (efecto en el próximo Testear)
  cfgToPreview({ type: 'config', sizes: sorted });
}

