function fillForm(map, data) {
  for (const [id, key] of Object.entries(map)) {
    const el = $(id); if (!el) continue;
    const v = data[key];
    if (el.type === 'checkbox') el.checked = v == null ? !!el.defaultChecked : !!v;
    else if (v != null) el.value = v;
  }
}
function readForm(map, types) {
  const out = {};
  for (const [id, key] of Object.entries(map)) {
    const el = $(id); if (!el) continue;
    if (el.type === 'checkbox') out[key] = el.checked;
    else if (types && types[key] === 'int') out[key] = parseInt(el.value, 10) || 0;
    else out[key] = el.value;
  }
  return out;
}
function syncBatVsPick(pickId, hiddenId) {
  const hid = $(hiddenId);
  const pick = $(pickId);
  if (!hid || !pick) return;
  const n = String(Math.max(1, Math.min(3, parseInt(hid.value, 10) || 1)));
  hid.value = n;
  pick.querySelectorAll('.bat-vs-opt').forEach((btn) => {
    btn.classList.toggle('is-on', btn.getAttribute('data-vs') === n);
  });
  if (!pick._batVsBound) {
    pick._batVsBound = true;
    pick.addEventListener('click', (e) => {
      const btn = e.target.closest('.bat-vs-opt');
      if (!btn) return;
      e.preventDefault();
      hid.value = btn.getAttribute('data-vs') || '1';
      syncBatVsPick(pickId, hiddenId);
      hid.dispatchEvent(new Event('change', { bubbles: true }));
    });
  }
}
function syncBatVsAdjust(prefix) {
  const scale = $(prefix + '-vsscale');
  const scaleLbl = $(prefix + '-vsscale-lbl');
  if (scale && scaleLbl) scaleLbl.textContent = Math.max(40, Math.min(180, parseInt(scale.value, 10) || 100)) + '%';
  const x = $(prefix + '-vsx');
  const xLbl = $(prefix + '-vsx-lbl');
  if (x && xLbl) {
    const n = Math.max(-80, Math.min(80, parseInt(x.value, 10) || 0));
    xLbl.textContent = (n > 0 ? '+' : '') + n;
  }
  const y = $(prefix + '-vsy');
  const yLbl = $(prefix + '-vsy-lbl');
  if (y && yLbl) {
    const n = Math.max(-80, Math.min(80, parseInt(y.value, 10) || 0));
    yLbl.textContent = (n > 0 ? '+' : '') + n;
  }
}
function syncBatCardClear(prefix) {
  const btn = $(prefix + '-cardclear');
  const bg = $(prefix + '-cardbg');
  const bd = $(prefix + '-cardborder');
  if (!btn) return;
  if (!btn._batClearBound) {
    btn._batClearBound = true;
    btn.addEventListener('click', (e) => {
      e.preventDefault();
      if (bg) {
        bg.disabled = false;
        bg.value = '#16262e';
        bg.dispatchEvent(new Event('input', { bubbles: true }));
      }
      if (bd) {
        bd.disabled = false;
        bd.value = '#94a3b8';
        bd.dispatchEvent(new Event('input', { bubbles: true }));
      }
    });
  }
}
function syncTopTextAdjust(prefix) {
  const syncScale = (id, lblId) => {
    const el = $(id);
    const lbl = $(lblId);
    if (el && lbl) lbl.textContent = Math.max(50, Math.min(180, parseInt(el.value, 10) || 100)) + '%';
  };
  const syncY = (id, lblId) => {
    const el = $(id);
    const lbl = $(lblId);
    if (el && lbl) {
      const n = Math.max(-80, Math.min(80, parseInt(el.value, 10) || 0));
      lbl.textContent = (n > 0 ? '+' : '') + n;
    }
  };
  syncScale(prefix + '-titlescale', prefix + '-titlescale-lbl');
  syncY(prefix + '-titley', prefix + '-titley-lbl');
  syncScale(prefix + '-bodyscale', prefix + '-bodyscale-lbl');
  syncY(prefix + '-bodyy', prefix + '-bodyy-lbl');
}
function enableModalDrag(modal) {
  const box = modal.querySelector('.modal-box');
  const head = box && box.querySelector('.modal-head');
  if (!box || !head || head._dragBound) return;
  head._dragBound = true;
  let dragging = false;
  let startX = 0, startY = 0, baseX = 0, baseY = 0, offX = 0, offY = 0;

  const apply = () => {
    box.style.transform = (offX || offY) ? `translate(${offX}px, ${offY}px)` : '';
  };
  const reset = () => { offX = 0; offY = 0; apply(); box.classList.remove('is-dragging'); };

  head.addEventListener('mousedown', (e) => {
    if (e.button !== 0) return;
    if (e.target.closest('button, a, input, select, textarea, label, .modal-close')) return;
    dragging = true;
    startX = e.clientX;
    startY = e.clientY;
    baseX = offX;
    baseY = offY;
    box.classList.add('is-dragging');
    e.preventDefault();
  });
  window.addEventListener('mousemove', (e) => {
    if (!dragging) return;
    const maxX = Math.max(120, window.innerWidth * 0.48);
    const maxY = Math.max(80, window.innerHeight * 0.48);
    offX = Math.max(-maxX, Math.min(maxX, baseX + (e.clientX - startX)));
    offY = Math.max(-maxY, Math.min(maxY, baseY + (e.clientY - startY)));
    apply();
  });
  window.addEventListener('mouseup', () => {
    if (!dragging) return;
    dragging = false;
    box.classList.remove('is-dragging');
  });

  let wasHidden = modal.classList.contains('hidden');
  new MutationObserver(() => {
    const nowHidden = modal.classList.contains('hidden');
    if (wasHidden && !nowHidden) reset();
    wasHidden = nowHidden;
  }).observe(modal, { attributes: true, attributeFilter: ['class'] });
}
function initModalDrag() {
  document.querySelectorAll('.modal').forEach(enableModalDrag);
}

function setupStyleOverlay(o) {
  const frame = () => $(o.previewId);
  const toPreview = (msg) => {
    ensureEmbedLoaded(frame()).then((fr) => {
      fr?.contentWindow?.postMessage({ kind: o.kind, ...msg }, '*');
    });
  };
  const buildCfg = () => readForm(o.map, o.types);
  const pushPreview = (cfg) => toPreview({ type: 'config', config: cfg || settings?.[o.settingsKey] || {} });
  const syncFormExtras = () => { if (typeof o.onFormSync === 'function') o.onFormSync(); };

  const bumpPreviewFrame = () => ensureEmbedLoaded(frame()).then((fr) => new Promise((resolve) => {
    if (!fr || !o.ovBuild) { resolve(); return; }
    const base = fr.getAttribute('src') || embedWantSrc(fr) || '/';
    const u = new URL(base, location.origin);
    u.searchParams.set('v', o.ovBuild);
    u.searchParams.set('_', String(Date.now()));
    const next = u.pathname + u.search;
    fr.dataset.src = next;
    fr.dataset.embedReady = '';
    const done = () => {
      fr.removeEventListener('load', done);
      fr.dataset.embedReady = '1';
      pushPreview();
      setTimeout(resolve, 120);
    };
    fr.addEventListener('load', done);
    fr.src = next;
  }));

  const runTest = async (fromModal) => {
    await ensureEmbedLoaded(frame());
    const extra = o.randomGift ? { gift: randomGiftSample() } : {};
    if (o.rank) extra.rank = o.rank;
    if (fromModal) {
      syncFormExtras();
      pushPreview(buildCfg());
    } else {
      pushPreview(settings?.[o.settingsKey] || {});
    }
    if (o.bumpPreview) await bumpPreviewFrame();
    const cfgNow = fromModal ? buildCfg() : (settings?.[o.settingsKey] || {});
    toPreview({ type: 'test', config: cfgNow, ...extra });
    send({ action: o.testAction, ...extra });
  };
  if ($(o.btnTest)) $(o.btnTest).onclick = () => runTest(false);
  if (o.btnTestModal && $(o.btnTestModal)) $(o.btnTestModal).onclick = () => runTest(true);
  if ($(o.btnReset)) $(o.btnReset).onclick = () => {
    toPreview({ type: 'reset' });
    send({ action: o.resetAction, ...(o.rank ? { rank: o.rank } : {}) });
    if (typeof o.onReset === 'function') o.onReset();
  };
  if ($(o.btnConfig)) $(o.btnConfig).onclick = async () => {
    await ensureEmbedLoaded(frame());
    fillForm(o.map, settings?.[o.settingsKey] || {});
    syncFormExtras();
    pushPreview(buildCfg());
    $(o.modalId).classList.remove('hidden');
  };
  const close = () => $(o.modalId).classList.add('hidden');
  if ($(o.closeId)) $(o.closeId).onclick = close;
  if ($(o.modalId)) $(o.modalId).addEventListener('click', (e) => { if (e.target.id === o.modalId) close(); });
  Object.keys(o.map).forEach((id) => {
    const el = $(id);
    if (el) {
      el.oninput = () => { syncFormExtras(); pushPreview(buildCfg()); };
      el.onchange = () => { syncFormExtras(); pushPreview(buildCfg()); };
    }
  });
  if ($(o.saveId)) $(o.saveId).onclick = () => {
    const cfg = { ...(settings[o.settingsKey] || {}), ...buildCfg() };
    settings[o.settingsKey] = cfg;
    if (o.onSave) o.onSave(cfg);
    saveSettings();
    pushPreview(settings[o.settingsKey]);
    close();
  };
  o._push = () => pushPreview();
  syncFormExtras();
  return o;
}

