  '😓':'sudando','🤗':'abrazo','🤔':'pensando','🤭':'risita','🤫':'silencio','🥱':'bostezo','😴':'dormido','😪':'sueño',
  '😬':'incómodo','🙄':'ojos en blanco','😶':'sin palabras','😐':'cara neutral','😑':'inexpresivo',
