function renderAcciones() {
  const grid = $('acc-grid');
  if (!grid) return;
  const list = (settings && settings.actions) || [];
  for (const id of [...accSelected]) if (!list.find((a) => a.id === id)) accSelected.delete(id);
  updateAccSelCount();
  syncAccViewToggleUI();

  if (!list.length) {
    grid.innerHTML = lcEmptyGuideHTML({
      title: 'Aún no tienes acciones',
      steps: ['Conecta TikTok', 'Crear acción', 'Probar tecla'],
      hint: 'Pulsa <b>Crear nueva acción</b> para empezar.',
      className: 'acc-empty empty',
    });
    return;
  }
  const q = getAccSearchQuery();
  const filtered = list.filter((a) => accMatchesSearch(a, q));
  if (!filtered.length) {
    grid.innerHTML = '<div class="acc-empty" id="acc-empty">Ninguna acción coincide con la búsqueda.</div>';
    return;
  }
  const mode = getAccViewMode();
  grid.innerHTML = filtered.map((a) => (mode === 'map' ? accMapCardHTML(a) : accListCardHTML(a))).join('');

  grid.querySelectorAll('.acc-card').forEach((card) => {
    const id = card.dataset.id;
    const a = list.find((x) => x.id === id);
    if (!a) return;
    card.querySelector('.acc-toggle').onchange = (e) => {
      a.enabled = e.target.checked;
      saveSettingsKeysPatch('actions');
      syncDesktopWebhookSettings();
      renderAcciones();
    };
    card.querySelector('.sa-sel').onchange = (e) => { e.target.checked ? accSelected.add(id) : accSelected.delete(id); updateAccSelCount(); };
    card.querySelector('.acc-edit').onclick = () => openAccModal(a);
    card.querySelector('.acc-try').onclick = () => scheduleActionTest(a);
    card.querySelector('.acc-try-now').onclick = () => runActionTestInstant(a);
    card.querySelector('.acc-dup').onclick = (e) => {
      e.preventDefault();
      e.stopPropagation();
      if (!ensureCanAdd('actions', 'actions', 'acciones')) return;
      duplicateSettingsItem('actions', id, {
        idPrefix: 'act',
        render: renderAcciones,
        save: () => {
          saveSettingsKeysPatch('actions');
          syncDesktopWebhookSettings();
        },
        toastMsg: 'Acción duplicada.',
      });
    };
    card.querySelector('.acc-del-one').onclick = async () => {
      const ok = await askConfirm({ title: 'Eliminar acción', message: `¿Eliminar "${a.name || 'Acción'}"?` });
      if (!ok) return;
      settings.actions = (settings.actions || []).filter((x) => x.id !== id);
      accSelected.delete(id);
      saveSettings();
      renderAcciones();
    };
  });
  if (!q) {
    bindSaCardLongPressReorder(grid, (ids) => {
      if (!applySettingsListOrder('actions', ids)) return;
      saveSettingsKeysPatch('actions');
      syncDesktopWebhookSettings();
    });
  }
}

function updateAccSelCount() {
  const c = $('acc-selcount');
  if (c) c.textContent = accSelected.size;
  const del = $('acc-del');
  if (del) del.disabled = accSelected.size === 0;
}

function accBind(id, fn, ev = 'onclick') {
  const el = $(id);
  if (!el) return false;
  if (ev === 'onchange') el.onchange = fn;
  else el.onclick = fn;
  return true;
}

function syncAccKeyRepeatUI() {
  const keysOn = $('acc-keys-on') && $('acc-keys-on').checked;
  if ($('acc-keyrepeat-on-row')) $('acc-keyrepeat-on-row').hidden = !keysOn;
  const repeatOn = keysOn && $('acc-keyrepeat-on') && $('acc-keyrepeat-on').checked;
  if ($('acc-keyrepeat-wrap')) $('acc-keyrepeat-wrap').hidden = !repeatOn;
  if ($('acc-keystagger-on-row')) $('acc-keystagger-on-row').hidden = !keysOn;
  const staggerOn = keysOn && $('acc-keystagger-on') && $('acc-keystagger-on').checked;
  if ($('acc-keystagger-wrap')) $('acc-keystagger-wrap').hidden = !staggerOn;
}

function syncAccWhStaggerUI() {
  const on = !!$('acc-wh-stagger-on')?.checked;
  if ($('acc-wh-stagger-wrap')) $('acc-wh-stagger-wrap').hidden = !on;
}

function syncAccSbStaggerUI() {
  const on = !!$('acc-sb-stagger-on')?.checked;
  if ($('acc-sb-stagger-wrap')) $('acc-sb-stagger-wrap').hidden = !on;
}

function parseTikfinitySpawnUrlMeta(url) {
  const u = String(url || '');
  if (!/\/spawn\b/i.test(u)) return null;
  const idM = u.match(/[?&](?:id|npcId)=(\d+)/i);
  if (!idM) return null;
  const qM = u.match(/[?&](?:quantity|count)=(\d+)/i);
  return { npcId: Number(idM[1]), quantity: qM ? Math.max(1, parseInt(qM[1], 10) || 1) : 1 };
}

function migrateAccionesSpawnWebhooks(actions) {
  if (!Array.isArray(actions)) return false;
  let changed = false;
  for (const a of actions) {
    if (a._spawnWebhookMigrated) continue;
    const meta = parseTikfinitySpawnUrlMeta(a?.webhookCmd?.url);
    if (a.marioSpawn?.npcId == null && meta && !a.webhookCmd?.on) {
      a.marioSpawn = meta;
      changed = true;
    }
    a._spawnWebhookMigrated = true;
  }
  return changed;
}

function tikfinityTypeToEvent(type) {
  if (type === 'gift') return 'gift';
  if (type === 'likes-person') return 'like';
  if (type === 'likes-total' || type === 'likes-global') return 'likeGlobal';
  if (type === 'follow') return 'follow';
  if (type === 'share') return 'share';
  if (type === 'subscribe') return 'subscribe';
  return null;
}

function tikfinityWebhookActionName(trig) {
  const gift = String(trig?.giftName || '').trim().toLowerCase();
  const clean = (s) => String(s || '').trim().replace(/^Gift\s+/i, '').trim();
  const candidates = [trig?.functionName, trig?.name, trig?.webhook?.name]
    .map(clean)
    .filter(Boolean);
  for (const c of candidates) {
    if (!gift || c.toLowerCase() !== gift) return c;
  }
  return candidates[0] || 'Acción TikFinity';
}

function setupAccionesUI() {
  if (window._accionesWired) return;
  if (!accBind('acc-new', () => {
    if (!ensureCanAdd('actions', 'actions', 'acciones')) return;
    openAccModal(null);
  })) return;
  window._accionesWired = true;
  wireMapViewControls('lc_acc_view', renderAcciones, 'acc-search');
  document.querySelectorAll('.acc-view-btn[data-acc-view]').forEach((btn) => {
    btn.onclick = (e) => {
      e.preventDefault();
      e.stopPropagation();
      setAccViewMode(btn.getAttribute('data-acc-view') || 'map');
    };
  });
  syncAccViewToggleUI();
  accBind('acc-del', async () => {
    if (!accSelected.size) return;
    const ok = await askConfirm({ title: 'Eliminar acciones', message: `Se eliminarán ${accSelected.size} acción(es).` });
    if (!ok) return;
    settings.actions = (settings.actions || []).filter((a) => !accSelected.has(a.id));
    accSelected.clear();
    saveSettings(); renderAcciones();
  });
  accBind('acc-toggle-all', () => {
    const list = settings.actions || [];
    if (!list.length) { toast('No hay acciones.', 'warn'); return; }
    const anyOff = list.some((a) => a.enabled === false);
    list.forEach((a) => { a.enabled = anyOff; });
    saveSettingsKeysPatch('actions');
    renderAcciones();
    toast(anyOff ? 'Todas las acciones encendidas.' : 'Todas las acciones apagadas.', 'ok');
  });
  accBind('acc-cancel', closeAccModal);
  accBind('acc-cancel2', closeAccModal);
  const accModal = $('accModal');
  if (accModal) accModal.addEventListener('click', (e) => { if (e.target.id === 'accModal') closeAccModal(); });
  accBind('acc-event', applyAccEventExtras, 'onchange');
  bindAccTrigGrid();
  syncAccTrigGrid();
  accBind('acc-giftpick', () => openGiftModalCb((g) => {
    $('acc-giftid').value = g.id || '';
    $('acc-giftname').value = g.name || '';
    accPendingGiftImage = g.image || '';
    $('acc-giftpick').innerHTML = giftBtnHTML(g.name, g.id);
  }));
  accBind('acc-emotepick', () => openEmoteModal('acc'));
  accBind('acc-keys-on', () => {
    const on = $('acc-keys-on').checked;
    $('acc-keys-box').hidden = !on;
    if (!on && $('acc-keyrepeat-on')) $('acc-keyrepeat-on').checked = false;
    if (!on && $('acc-keystagger-on')) $('acc-keystagger-on').checked = false;
    syncAccKeyRepeatUI();
    if (on && !$('acc-keys').value.trim()) openKeyboardModal();
  });
  accBind('acc-keyrepeat-on', syncAccKeyRepeatUI);
  accBind('acc-keystagger-on', syncAccKeyRepeatUI);
  accBind('acc-keypick', openKeyboardModal);
  accBind('acc-keyclear', () => { $('acc-keys').value = ''; accPendingGameCompat = false; accPendingKeyHoldSec = 0; });
  accBind('acc-imgbtn', () => $('acc-imgfile')?.click());
  const imgFile = $('acc-imgfile');
  if (imgFile) imgFile.addEventListener('change', (e) => uploadAccImage(e.target.files[0]));
  accBind('acc-soundon', () => {
    const on = $('acc-soundon').checked;
    $('acc-soundbox').hidden = !on;
    $('acc-volrow').hidden = !(on && accPendingSound);
    if (on && !accPendingSound) { soundPickTarget = 'action'; openSoundLib(); }
  });
  accBind('acc-soundpick', () => { soundPickTarget = 'action'; openSoundLib(); });
  accBind('acc-soundclear', () => {
    accPendingSound = null;
    $('acc-soundname').textContent = 'Ningún audio…';
    $('acc-volrow').hidden = true;
  });
  const volEl = $('acc-soundvol');
  if (volEl) volEl.addEventListener('input', () => { $('acc-soundvolval').textContent = volEl.value + '%'; });
  // Salidas extra: WebHook / OBS / Streamer.bot.
  accBind('acc-wh-on', () => {
    $('acc-wh-box').hidden = !$('acc-wh-on').checked;
    if (!$('acc-wh-on').checked && $('acc-wh-stagger-on')) $('acc-wh-stagger-on').checked = false;
    syncAccWhStaggerUI();
  });
  accBind('acc-wh-stagger-on', syncAccWhStaggerUI);
  accBind('acc-obs-on', () => { $('acc-obs-box').hidden = !$('acc-obs-on').checked; });
  accBind('acc-sb-on', () => {
    $('acc-sb-box').hidden = !$('acc-sb-on').checked;
    if (!$('acc-sb-on').checked && $('acc-sb-stagger-on')) $('acc-sb-stagger-on').checked = false;
    syncAccSbStaggerUI();
  });
  accBind('acc-sb-stagger-on', syncAccSbStaggerUI);
  accBind('acc-obs-type', applyObsCmdExtras, 'onchange');
  accBind('acc-media-on', () => {
    $('acc-media-box').hidden = !$('acc-media-on').checked;
    refreshAccMediaScreenUrl();
  });
  accBind('acc-media-screen', refreshAccMediaScreenUrl, 'onchange');
  accBind('acc-media-copy-url', () => {
    const url = $('acc-media-ls-url')?.textContent?.trim() || '';
    if (!url) return;
    navigator.clipboard?.writeText(url);
    toast('Link copiado — pégalo en Live Studio', 'ok');
  });
  accBind('acc-media-upbtn', () => $('acc-media-file')?.click());
  setupAccMediaDrop();
  accBind('acc-test', () => scheduleActionTest(readAccTestAction()));
  accBind('acc-test-now', () => runActionTestInstant(readAccTestAction()));
  accBind('acc-save', saveAccModal);
  setupKeyboardModal();
}

let accPendingGiftImage = '';
let accPendingSound = null;   // { url, name }
let accPendingMedia = null;   // { url, name }

function readAccTestAction() {
  return {
    name: $('acc-name').value.trim() || 'Prueba',
    keys: $('acc-keys-on').checked ? $('acc-keys').value.trim() : '',
    gameCompat: accPendingGameCompat,
    keyHoldSec: accPendingKeyHoldSec,
    keyRepeatOn: $('acc-keyrepeat-on')?.checked,
    keyRepeat: Math.max(1, parseInt($('acc-keyrepeat')?.value, 10) || 1),
    keyStaggerOn: !!$('acc-keystagger-on')?.checked,
    keyStaggerMs: Math.max(50, Math.min(10000, parseInt($('acc-keystagger-ms')?.value, 10) || 300)),
    sound: $('acc-soundon').checked && accPendingSound ? accPendingSound.url : '',
    soundVolume: Math.max(0, Math.min(1, (+$('acc-soundvol').value || 100) / 100)),
    webhookCmd: readAccWebhookCmd(),
    obsCmd: readAccObsCmd(),
    sbCmd: readAccSbCmd(),
    mediaShow: readAccMediaShow(),
  };
}
function readAccMediaShow() {
  const on = !!$('acc-media-on')?.checked;
  if (!on) return { on: false, url: '', name: '', size: 100, volume: 100, screen: 1, originalDuration: true };
  return {
    on: true,
    url: accPendingMedia?.url || '',
    name: accPendingMedia?.name || '',
    size: Math.max(10, Math.min(100, parseInt($('acc-media-size')?.value, 10) || 100)),
    volume: Math.max(0, Math.min(100, parseInt($('acc-media-vol')?.value, 10) || 100)),
    screen: Math.max(1, Math.min(SCREEN_COUNT, parseInt($('acc-media-screen')?.value, 10) || 1)),
    originalDuration: $('acc-media-orig')?.checked !== false,
  };
}

async function uploadAccMediaFile(file) {
  if (!file) return;
  const label = $('acc-media-fname');
  try {
    const data = await uploadMediaWithProgress(file, (msg) => { if (label) label.textContent = msg; });
    accPendingMedia = { url: data.url, name: file.name };
    if (label) label.textContent = file.name;
  } catch (err) {
    if (label) label.textContent = uploadErrLabel(err);
  }
}

function setupAccMediaDrop() {
  const drop = $('acc-media-drop');
  const input = $('acc-media-file');
  if (!drop || !input || drop.dataset.wired) return;
  drop.dataset.wired = '1';
  const stop = (e) => { e.preventDefault(); e.stopPropagation(); };
  ['dragenter', 'dragover'].forEach((ev) => {
    drop.addEventListener(ev, (e) => { stop(e); drop.classList.add('is-drag'); });
  });
  ['dragleave', 'drop'].forEach((ev) => {
    drop.addEventListener(ev, (e) => { stop(e); drop.classList.remove('is-drag'); });
  });
  drop.addEventListener('drop', (e) => {
    const file = e.dataTransfer?.files?.[0];
    if (file) uploadAccMediaFile(file);
  });
  input.addEventListener('change', async (e) => {
    const file = e.target.files?.[0];
    if (file) await uploadAccMediaFile(file);
    e.target.value = '';
  });
}

function ensureAccEditId() {
  if (accEditingId) return accEditingId;
  accEditingId = 'act' + Date.now();
  return accEditingId;
}

function applyAccEventExtras() {
  const ev = $('acc-event').value;
  $('acc-giftanyextra').hidden = ev !== 'gift-any';
  $('acc-giftextra').hidden = ev !== 'gift';
  $('acc-likeextra').hidden = ev !== 'like';
  $('acc-likeglobalextra').hidden = ev !== 'likeGlobal';
  $('acc-emoteextra').hidden = ev !== 'emote';
  if ($('acc-eventdelayextra')) $('acc-eventdelayextra').hidden = ev !== 'emote';
  if ($('acc-cmdextra')) $('acc-cmdextra').hidden = ev !== 'chatCommand';
  if ($('acc-userextra')) $('acc-userextra').hidden = ev !== 'chatCommand';
  if ($('acc-combo-row')) $('acc-combo-row').hidden = ev !== 'gift' && ev !== 'gift-any';
  syncAccTrigGrid();
}

function syncAccTrigGrid() {
  syncTrigSelectGrid('acc-trig-grid', 'acc-event', 'gift-any');
}

function bindAccTrigGrid() {
  bindTrigSelectGrid('acc-trig-grid', 'acc-event');
}

/** Sincroniza rejilla visual ↔ select oculto (acciones / sonoras / videos / batallas). */
function syncTrigSelectGrid(gridId, selectId, fallback = '') {
  const v = $(selectId)?.value || fallback;
  const grid = $(gridId);
  if (!grid) return;
  grid.querySelectorAll('.acc-trig-item').forEach((btn) => {
    const on = btn.dataset.v === v;
    btn.classList.toggle('is-on', on);
    btn.setAttribute('aria-selected', on ? 'true' : 'false');
  });
}

function bindTrigSelectGrid(gridId, selectId) {
  const grid = $(gridId);
  if (!grid || grid.dataset.bound === '1') return;
  grid.dataset.bound = '1';
  grid.addEventListener('click', (e) => {
    const btn = e.target.closest('.acc-trig-item');
    if (!btn || !grid.contains(btn)) return;
    const sel = $(selectId);
    if (!sel) return;
    const next = btn.dataset.v;
    if (!next || sel.value === next) {
      syncTrigSelectGrid(gridId, selectId);
      return;
    }
    sel.value = next;
    sel.dispatchEvent(new Event('change', { bubbles: true }));
  });
}

// Muestra los campos de escena/fuente según el tipo de comando de OBS elegido.
