const GAME_ACTION_RENDERERS = {};
function registerGameActionRenderer(settingsKey, fn) {
  if (!settingsKey || typeof fn !== 'function') return;
  const prev = GAME_ACTION_RENDERERS[settingsKey];
  if (prev && prev._lcOrig === fn) return;
  if (fn._lcGameViewWrapped) {
    GAME_ACTION_RENDERERS[settingsKey] = fn;
    return;
  }
  const wrapped = function lcGameRenderWrapped() {
    const out = fn.apply(this, arguments);
    try { queueMicrotask(() => prepareAllGameActionsViews()); } catch { try { prepareAllGameActionsViews(); } catch {} }
    return out;
  };
  wrapped._lcGameViewWrapped = true;
  wrapped._lcOrig = fn;
  GAME_ACTION_RENDERERS[settingsKey] = wrapped;
}

function findAnyGameAction(uid) {
  if (!uid || !settings) return null;
  const mcHit = findMcFamilyAction(uid);
  if (mcHit) return mcHit;
  for (const key of (typeof GAME_ACTION_SETTINGS_KEYS !== 'undefined' ? GAME_ACTION_SETTINGS_KEYS : [])) {
    const list = settings[key];
    if (!Array.isArray(list)) continue;
    const action = list.find((x) => x && x.uid === uid);
    if (action) return { action, key, render: GAME_ACTION_RENDERERS[key] || (() => {}) };
  }
  return null;
}

/** Copia una acción de juego e inserta el duplicado justo debajo. */
function duplicateGameActionBelow(settingsKey, uid, render) {
  const list = settings?.[settingsKey];
  if (!Array.isArray(list) || !uid) return;
  const idx = list.findIndex((x) => x && x.uid === uid);
  if (idx < 0) return;
  const src = list[idx];
  const copy = JSON.parse(JSON.stringify(src));
  const prefix = String(src.uid || 'act').split('_')[0] || 'act';
  copy.uid = `${prefix}_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`;
  list.splice(idx + 1, 0, copy);
  lastGameActionEditAt = Date.now();
  saveSettingsKeysPatch(settingsKey);
  notifyEditorRapidoActionsChanged(settingsKey);
  if (typeof render === 'function') render();
  toast && toast('Acción duplicada.', 'ok');
}

function bindGameSurvivalCardExtras(wrap, find, render, opts = {}) {
  try { prepareGameActionsView(wrap); } catch {}
  const settingsKey = opts.settingsKey;
  wrap.querySelectorAll('.mc-trig-icon-btn').forEach((b) => {
    b.onclick = () => openMcTrigPop(b.dataset.uid, settingsKey);
  });
  wrap.querySelectorAll('.mc-act-en').forEach((c) => {
    c.onchange = () => {
      const id = c.dataset.uid || c.dataset.slot;
      const a = find(id);
      if (!a) return;
      a.enabled = c.checked;
      lastGameActionEditAt = Date.now();
      // Solo Activa ON/OFF: no reconstruir Editor Pro. Flush al apagar → el live no spawnea.
      if (settingsKey) {
        saveSettingsKeysPatch(settingsKey, { skipErSync: true, flush: !c.checked });
      } else if (!c.checked) flushSaveSettings();
      else saveSettings();
      render();
    };
  });
  wrap.querySelectorAll('.mc-act-dup').forEach((b) => {
    b.onclick = () => {
      if (!settingsKey || !b.dataset.uid) return;
      duplicateGameActionBelow(settingsKey, b.dataset.uid, render);
    };
  });
  const warnLiveNeedsOn = (el) => {
    const a = find(el?.dataset?.uid || el?.dataset?.slot);
    if (a && a.enabled === false) {
      toast && toast('Probar sí funciona apagada, pero en el live hace falta ENCENDERLA (toggle Activa / Encender todas).', 'warn');
    }
  };
  const runTest = (el) => {
    warnLiveNeedsOn(el);
    if (opts.onTest) opts.onTest(el);
    else if (opts.testFn) {
      const a = find(el.dataset.uid || el.dataset.slot);
      if (a) opts.testFn(a);
    }
  };
  wrap.querySelectorAll('.mc-act-test-delay').forEach((b) => {
    b.onclick = () => {
      const delayMs = Math.max(0, Number(opts.testDelayMs) || 4000);
      const sec = Math.round(delayMs / 1000);
      toast && toast(sec > 0 ? `La acción se ejecutará en ${sec} segundo${sec === 1 ? '' : 's'}…` : 'Ejecutando…', 'ok');
      if (delayMs <= 0) runTest(b);
      else setTimeout(() => runTest(b), delayMs);
    };
  });
  if (opts.testClass) {
    wrap.querySelectorAll(`.${opts.testClass}`).forEach((b) => {
      b.onclick = () => runTest(b);
    });
  }
  bindMcFamilyAudio(wrap, find, render);
  bindMcActionCardCommon(wrap, find, render);
}

function gameActionCardFooter(a, testClass, opts = {}) {
  registerGameActionCfgOpts(a, opts);
  const testBtn = opts.hideTest
    ? ''
    : (opts.slot != null
      ? `<button type="button" class="mc-act-test ${testClass}" data-slot="${opts.slot}">Probar</button>`
      : `<button type="button" class="mc-act-test ${testClass}" data-uid="${esc(a.uid)}">Probar</button>`);
  const editBtn = opts.editBtn || '';
  return `
    <div class="mc-act-actions">
      <div class="mc-act-btns">
        ${gameActionConfigBtnHtml(a, opts)}
        ${editBtn}
        ${testBtn}
      </div>
    </div>`;
}

async function runTimedGameActionTest(a, fn, testOpts = {}) {
  ensureGameActionTimingFields(a);
  const timingMode = testOpts.timingMode ?? 'count';
  const delayBefore = Math.max(0, parseInt(a.delayBefore ?? a.delayGroup, 10) || 0);
  const delayEach = Math.max(0, parseInt(a.delayEach, 10) || 100);
  const loops = timingMode === 'count'
    ? Math.max(1, parseInt(a.count, 10) || 1)
    : Math.max(1, parseInt(a.repeat, 10) || 1);
  const wait = (ms) => new Promise((r) => setTimeout(r, ms));
  if (delayBefore) await wait(delayBefore);
  for (let i = 0; i < loops; i++) {
    await fn(i);
    if (i < loops - 1 && delayEach) await wait(delayEach);
  }
}

function bindGameActionConfigPopovers(wrap, find, render, opts = {}) {
  const useSlot = !!opts.useSlot;
  const cfgKeyToId = (key) => (useSlot ? key.replace(/^slot:/, '') : key.replace(/^uid:/, ''));
  wrap.querySelectorAll('.mc-act-cfg-btn').forEach((btn) => {
    btn.onclick = (e) => {
      e.stopPropagation();
      const cfgKey = btn.dataset.cfgKey;
      const cardOpts = _gameActCfgOptsMap.get(cfgKey) || {};
      const id = cfgKeyToId(cfgKey);
      const a = find(id);
      if (!a) return;
      openGameActionConfigModal(a, cardOpts, {
        find,
        render,
        wrap,
        useSlot,
        key: id,
        cardOpts,
        opts,
      });
    };
  });
}

