// Bloquea la pestaña Webhook con aviso Premium; Configuración queda en su propia pestaña.
function applyWebhookLock() {
  const banner = document.getElementById('wh-premium');
  const webhookPanel = document.getElementById('wtab-webhook');
  const locked = IS_DESKTOP && !webhookUnlocked();
  if (webhookPanel) webhookPanel.classList.toggle('wh-locked', locked);
  if (banner) banner.hidden = !locked;
}

function webhookCfg() {
  const c = settings && settings.webhook ? settings.webhook : {};
  return {
    rcon: { ...WEBHOOK_DEFAULTS.rcon, ...(c.rcon || {}) },
    obs: { ...WEBHOOK_DEFAULTS.obs, ...(c.obs || {}) },
    streamerbot: { ...WEBHOOK_DEFAULTS.streamerbot, ...(c.streamerbot || {}) },
    servertap: { ...WEBHOOK_DEFAULTS.servertap, ...(c.servertap || {}) },
  };
}

// settings.webhook -> formulario.
function applyWebhookUI() {
  if (!settings) return;
  const cfg = webhookCfg();
  for (const [id, [grp, key]] of Object.entries(WEBHOOK_MAP)) {
    const el = document.getElementById(id);
    if (!el) continue;
    if (el.type === 'checkbox') el.checked = !!cfg[grp][key];
    else el.value = cfg[grp][key];
  }
  const rpc = document.getElementById('wh-rcon-player');
  if (rpc && !String(rpc.value || '').trim() && cfg.servertap.playername) rpc.value = cfg.servertap.playername;
}
// Formulario -> settings.webhook y guarda.
function saveWebhookSettings() {
  if (!settings) return;
  const cfg = webhookCfg();
  for (const [id, [grp, key]] of Object.entries(WEBHOOK_MAP)) {
    const el = document.getElementById(id);
    if (!el) continue;
    if (el.type === 'checkbox') cfg[grp][key] = el.checked;
    else if (el.type === 'number') cfg[grp][key] = parseInt(el.value, 10) || 0;
    else cfg[grp][key] = el.value;
  }
  cfg.servertap.playername = String(cfg.rcon.playername || cfg.servertap.playername || '').trim();
  settings.webhook = cfg;
  saveSettings();
}

/** Sincroniza ServerTap desde pestaña Servidor Minecraft → Configuración global (Acciones). */
window.syncMcservServerTap = function syncMcservServerTap(stap) {
  if (!settings) return;
  const s = stap || {};
  settings.webhook = settings.webhook || {};
  settings.webhook.servertap = {
    ...WEBHOOK_DEFAULTS.servertap,
    ...(settings.webhook.servertap || {}),
    enabled: s.enabled !== false,
    ip: String(s.ip || 'localhost').trim() || 'localhost',
    port: parseInt(s.port, 10) || 4567,
    key: String(s.key || 'tiktok123').trim() || 'tiktok123',
    playername: String(s.playername || '@p').trim() || '@p',
  };
  const rpc = document.getElementById('wh-rcon-player');
  if (rpc && s.playername && s.playername !== '@p') rpc.value = s.playername;
  saveSettings();
  if (typeof applyWebhookUI === 'function') applyWebhookUI();
};

let webhookWired = false;
function syncWebhookRoomUrls() {
  // Webhook local (:3199). Preferimos la clave local; si no hay, la de la nube
  // (también válida tras el arreglo del webhook). No toca URLs de overlays.
  const room = String(window.ROOM_KEY || window.CLOUD_ROOM_KEY || '').trim();
  const keyEl = document.getElementById('wh-room-key');
  const line = document.getElementById('wh-room-line');
  if (keyEl) keyEl.textContent = room || '— (inicia sesión)';
  if (line) line.hidden = false;

  document.querySelectorAll('#view-webhook code.wh-url').forEach((code) => {
    let t = (code.textContent || '').trim();
    if (!/localhost:3199/i.test(t) && !code.dataset.whBase) return;
    if (!code.dataset.whBase) {
      code.dataset.whBase = t
        .replace(/[?&]room=[^&\s]*/gi, '')
        .replace(/\?&/, '?')
        .replace(/\?$/, '')
        .replace(/&$/, '');
    }
    const base = code.dataset.whBase;
    if (!base) return;
    if (!room) {
      code.textContent = base.includes('?') ? `${base}&room=…` : `${base}?room=…`;
      return;
    }
    code.textContent = base.includes('?')
      ? `${base}&room=${encodeURIComponent(room)}`
      : `${base}?room=${encodeURIComponent(room)}`;
  });
}
function setupWebhookUI() {
  if (!webhookWired) {
    webhookWired = true;

    document.querySelectorAll('#view-webhook .wh-endpoint .wh-copy').forEach((btn) => {
      btn.onclick = () => {
        syncWebhookRoomUrls();
        const code = btn.parentElement.querySelector('.wh-url');
        if (!code) return;
        const text = code.textContent;
        if (!window.ROOM_KEY) {
          toast && toast('Inicia sesión para copiar la URL con tu room.', 'warn');
        }
        const done = () => { btn.classList.add('ok'); setTimeout(() => btn.classList.remove('ok'), 1200); };
        if (navigator.clipboard?.writeText) navigator.clipboard.writeText(text).then(done).catch(() => fallbackCopy(text, done));
        else fallbackCopy(text, done);
      };
    });

    const copyKey = document.getElementById('wh-room-copy');
    if (copyKey) {
      copyKey.onclick = () => {
        const room = String(window.ROOM_KEY || '').trim();
        if (!room) { toast && toast('No hay clave de sala. Inicia sesión.', 'warn'); return; }
        const done = () => { toast && toast('Clave copiada', 'ok'); };
        if (navigator.clipboard?.writeText) navigator.clipboard.writeText(room).then(done).catch(() => fallbackCopy(room, done));
        else fallbackCopy(room, done);
      };
    }

    const flashSaved = () => {
      const msg = document.getElementById('wh-save-msg');
      if (msg) { msg.textContent = '✓ Guardado'; clearTimeout(flashSaved._t); flashSaved._t = setTimeout(() => { msg.textContent = ''; }, 1500); }
    };
    let whTimer = null;
    const autoSave = () => { clearTimeout(whTimer); whTimer = setTimeout(() => { saveWebhookSettings(); flashSaved(); }, 350); };
    for (const id of Object.keys(WEBHOOK_MAP)) {
      const el = document.getElementById(id);
      if (el) el.addEventListener('input', autoSave);
    }

    document.querySelectorAll('#view-configuracion .wh-test').forEach((btn) => {
      btn.onclick = () => testWebhookConnection(btn.dataset.test, btn);
    });
  }

  syncWebhookRoomUrls();
  applyWebhookUI();
  applyWebhookLock();
}

async function testWebhookConnection(kind, btn) {
  saveWebhookSettings();
  const cfg = webhookCfg();
  const msgId = kind === 'rcon' ? 'wh-rcon-msg' : kind === 'obs' ? 'wh-obs-msg' : kind === 'servertap' ? 'wh-stap-msg' : 'wh-sb-msg';
  const msg = document.getElementById(msgId);
  const setMsg = (t, cls) => { if (msg) { msg.textContent = t; msg.className = 'wh-test-msg ' + cls; } };
  let body, url;
  if (kind === 'rcon') { url = '/api/webhook/test-rcon'; body = cfg.rcon; }
  else if (kind === 'obs') { url = '/api/webhook/test-obs'; body = cfg.obs; }
  else if (kind === 'servertap') { url = '/api/webhook/test-servertap'; body = cfg.servertap; }
  else { url = '/api/webhook/test-streamerbot'; body = cfg.streamerbot; }
  setMsg('Probando…', 'run');
  if (btn) btn.disabled = true;
  try {
    const r = await fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
    const d = await r.json();
    if (d.ok) setMsg('✓ Conexión correcta', 'ok');
    else setMsg('✗ ' + (d.error || 'No se pudo conectar'), 'err');
  } catch {
    setMsg('✗ Error de red', 'err');
  } finally {
    if (btn) btn.disabled = false;
  }
}

/* ===== Pantalla de inicio: hero de estado del live ===== */
function homeLastUser() {
  let u = '';
  try { u = ($('username') && $('username').value || '').trim(); } catch {}
  if (!u) { try { u = (getLastTikTokUserPref() || '').trim(); } catch {} }
  return u.replace(/^@/, '');
}

function formatLiveDuration(ms) {
  const t = Math.max(0, Math.floor(Number(ms) / 1000) || 0);
  const h = Math.floor(t / 3600);
  const m = Math.floor((t % 3600) / 60);
  const s = t % 60;
  const pad = (n) => String(n).padStart(2, '0');
  return h > 0 ? `${pad(h)}:${pad(m)}:${pad(s)}` : `${pad(m)}:${pad(s)}`;
}

let homeLiveStartedAt = null;
let homeLiveTimer = null;

function stopHomeLiveTimer() {
  if (homeLiveTimer) { clearInterval(homeLiveTimer); homeLiveTimer = null; }
}

function tickHomeLiveTimer() {
  const timeWrap = document.getElementById('home-hero-time');
  const timeVal = document.getElementById('home-hero-time-val');
  if (!timeWrap || !timeVal || !homeLiveStartedAt) return;
  timeVal.textContent = formatLiveDuration(Date.now() - homeLiveStartedAt);
}

function updateHomeHeroAvatar({ photo, nickname, username, mode } = {}) {
  const wrap = document.getElementById('home-hero-av');
  const img = document.getElementById('home-hero-img');
  const ph = document.getElementById('home-hero-ph');
  if (!wrap || !img || !ph) return;
  if (photo) connectStreamerPhoto = photo;
  const name = nickname || username || homeLastUser() || '';
  const url = connectAvatarUrl(photo || connectStreamerPhoto);
  wrap.classList.remove('live', 'wait');
  if (mode === 'live') wrap.classList.add('live');
  else if (mode === 'wait') wrap.classList.add('wait');
  if (url) {
    img.referrerPolicy = 'no-referrer';
    img.src = url;
    img.hidden = false;
    ph.hidden = true;
    img.onerror = () => {
      img.hidden = true;
      ph.hidden = false;
      ph.textContent = initial(name);
    };
  } else {
    img.hidden = true;
    ph.hidden = false;
    ph.textContent = initial(name || '?');
  }
  try { updateDockUserAvatar({ photo: photo || connectStreamerPhoto, nickname: name, username: username || window.MY_USER }); } catch {}
}

function syncHomeHeroPlan() {
  const hero = document.getElementById('home-welcome');
  const tier = document.getElementById('home-hero-tier');
  if (!hero) return;
  const isPremium = !!(window.IS_ADMIN || window.CAPS?.plan === 'premium' || window.MY_PLAN === 'premium' || window.MY_PLAN === 'founder');
  hero.classList.toggle('is-vip', isPremium);
  hero.classList.toggle('is-free', !isPremium);
  if (tier) {
    const isFounder = String(window.MY_PLAN || '').toLowerCase() === 'founder';
    tier.textContent = isFounder ? 'Founder' : (isPremium ? 'VIP' : 'Free');
    tier.className = 'home-hero-tier ' + (isPremium ? 'vip' : 'free');
  }
}

function updateHomeWelcome(s) {
  const userEl = document.getElementById('home-hero-user');
  const badge = document.getElementById('home-hero-badge');
  const sub = document.getElementById('home-hero-sub');
  const btn = document.getElementById('home-welcome-btn');
  const timeWrap = document.getElementById('home-hero-time');
  if (!userEl || !badge) return;

  const user = (s && s.username) ? String(s.username).replace(/^@/, '') : homeLastUser();
  const nick = (s && s.nickname) ? String(s.nickname).trim() : '';
  userEl.textContent = user ? `@${user}` : 'Sin cuenta conectada';

  let mode = 'off';
  let badgeText = 'Desconectado';
  let subText = 'Conecta tu cuenta de TikTok para empezar el directo.';

  if (s && s.connected) {
    mode = 'live';
    badgeText = 'En vivo';
    subText = nick ? `${nick} · directo activo` : 'Directo activo';
  } else if (s && s.connecting) {
    mode = 'wait';
    badgeText = 'Conectando';
    subText = user ? `Conectando con @${user}…` : 'Conectando…';
  } else if (s && s.autoConnect && user) {
    mode = 'wait';
    badgeText = 'Esperando';
    subText = `Esperando que @${user} inicie el live…`;
  } else if (user) {
    subText = 'Listo para conectar. Pulsa Conectar cuando vayas a transmitir.';
  }

  badge.className = `home-hero-badge ${mode}`;
  badge.textContent = badgeText;
  if (sub) sub.textContent = subText;
  if (btn) {
    btn.style.display = (s && s.connected) ? 'none' : '';
    btn.textContent = (s && s.autoConnect && user && !(s && s.connected)) ? 'Reconectar' : 'Conectar';
  }

  updateHomeHeroAvatar({
    photo: s?.photo,
    nickname: nick || user,
    username: user,
    mode,
  });
  syncHomeHeroPlan();

  if (s && s.connected) {
    const started = Number(s.startedAt) || homeLiveStartedAt || Date.now();
    homeLiveStartedAt = started;
    if (timeWrap) timeWrap.hidden = false;
    tickHomeLiveTimer();
    if (!homeLiveTimer) homeLiveTimer = setInterval(tickHomeLiveTimer, 1000);
  } else {
    homeLiveStartedAt = null;
    stopHomeLiveTimer();
    if (timeWrap) timeWrap.hidden = true;
  }
}

function initHomeWelcome() {
  syncHomeHeroPlan();
  updateHomeWelcome(null);
  const btn = document.getElementById('home-welcome-btn');
  if (btn) {
    btn.onclick = () => {
      const inp = $('username');
      if (inp && !inp.value.trim()) { const u = homeLastUser(); if (u) inp.value = u; }
      if (typeof doConnect === 'function') doConnect();
    };
  }
}

let panelLivesTimer = null;

/* ====================== Ranking semanal streamers ====================== */
let srkType = 'likes';
let srkTimer = null;
let srkWired = false;

function srkLimit() {
  const el = document.getElementById('srk-limit');
  const n = el ? Number(el.value) : 10;
  return Math.min(100, Math.max(3, Number.isFinite(n) ? n : 10));
}

function fmtSrkReset(resetAt) {
  const ms = Math.max(0, (resetAt || 0) - Date.now());
  const d = Math.floor(ms / 86400000);
  const h = Math.floor((ms % 86400000) / 3600000);
  const m = Math.floor((ms % 3600000) / 60000);
  if (d > 0) return `${d}d ${h}h`;
  if (h > 0) return `${h}h ${m}m`;
  return `${m}m`;
}

function fmtSrkWeekRange(start, end) {
  try {
    const a = new Date(start).toLocaleDateString('es', { day: 'numeric', month: 'short' });
    const b = new Date(end - 1).toLocaleDateString('es', { day: 'numeric', month: 'short' });
    return `${a} – ${b}`;
  } catch { return ''; }
}

function fmtSrkDayLabel(key) {
  try {
    const [y, mo, d] = key.split('-').map(Number);
    const dt = new Date(y, mo - 1, d);
    return dt.toLocaleDateString('es', { weekday: 'short', day: 'numeric' });
  } catch { return key; }
}

const SRK_DOW_SHORT = ['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'];

function srkDayKeyFromDate(d) {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

function srkWeekTimeline(weekStart) {
  const todayKey = srkDayKeyFromDate(new Date());
  const start = new Date(weekStart);
  const cells = [];
  for (let i = 0; i < 7; i++) {
    const d = new Date(start.getFullYear(), start.getMonth(), start.getDate() + i);
    const key = srkDayKeyFromDate(d);
    const dow = d.getDay();
    cells.push({
      key,
      dow,
      sort: dow === 0 ? 7 : dow,
      label: SRK_DOW_SHORT[dow],
      num: d.getDate(),
      isToday: key === todayKey,
      isFuture: key > todayKey,
    });
  }
  return cells.sort((a, b) => a.sort - b.sort);
}

function renderSrkTimeline(daysMap, weekStart, isLikes, valLabel) {
  const timeline = srkWeekTimeline(weekStart);
  const cells = timeline.map((day) => {
    const dv = daysMap[day.key] || {};
    const v = isLikes ? (dv.likes || 0) : (dv.diamonds || 0);
    const h = Math.round((dv.streamMs || 0) / 36000) / 100;
    const has = v > 0 || h > 0;
    const cls = ['srk-tl-cell', day.isToday && 'today', has && 'has-data', day.isFuture && !has && 'future'].filter(Boolean).join(' ');
    const tip = `${day.label} ${day.num}: ${has ? `${fmt(v)} ${valLabel}` : 'sin actividad'}${h > 0 ? ` · ${h}h` : ''}`;
    return `<div class="${cls}" title="${esc(tip)}">
      <span class="srk-tl-dow">${day.label}</span>
      <span class="srk-tl-num">${day.num}</span>
      <span class="srk-tl-val">${has ? fmt(v) : '—'}</span>
      <span class="srk-tl-h">${h > 0 ? `${h}h` : '·'}</span>
    </div>`;
  }).join('');
  return `<div class="srk-timeline"><div class="srk-tl-grid">${cells}</div></div>`;
}

function renderStreamerRanking(data) {
  const list = document.getElementById('srk-list');
  const resetEl = document.getElementById('srk-reset');
  if (!list) return;
  if (!data) {
    list.innerHTML = '<p class="srk-empty">No se pudo cargar el ranking.</p>';
    return;
  }
  const isLikes = data.type === 'likes';
  const valKey = isLikes ? 'likesWeek' : 'diamondsWeek';
  const valLabel = isLikes ? 'likes' : 'diamantes';
  if (resetEl) {
    resetEl.textContent = `Semana ${fmtSrkWeekRange(data.weekStart, data.weekEnd)} · Reinicio en ${fmtSrkReset(data.resetAt)} (lunes 00:00)`;
  }
  const entries = data.entries || [];
  if (!entries.length) {
    list.innerHTML = '<p class="srk-empty">Aún no hay datos esta semana. Conecta tu live para sumar al ranking.</p>';
    return;
  }
  list.innerHTML = entries.map((e) => {
    const name = esc(e.nickname || e.tiktok || e.username || 'Streamer');
    const handle = e.tiktok ? `@${esc(e.tiktok)}` : (e.username ? `@${esc(e.username)}` : '');
    const photoUrl = e.photo ? panelLiveImgUrl(e.photo) : '';
    const av = photoUrl
      ? `<img class="srk-av" src="${esc(photoUrl)}" alt="" loading="lazy" referrerpolicy="no-referrer" onerror="this.replaceWith(Object.assign(document.createElement('div'),{className:'srk-ph',textContent:'${initial(e.nickname || e.tiktok || '?')}' }))">`
      : `<div class="srk-ph">${initial(e.nickname || e.tiktok || '?')}</div>`;
    const timeline = renderSrkTimeline(e.days || {}, data.weekStart, isLikes, valLabel);
    return `<article class="srk-row${e.rank === 1 ? ' top1' : ''}">
      <div class="srk-rank">#${e.rank}</div>
      ${av}
      <div><div class="srk-name">${name}</div>${handle ? `<div class="srk-handle">${handle}</div>` : ''}</div>
      <div class="srk-meta">
        <div class="srk-val">${fmt(e[valKey] || 0)}</div>
        <div class="srk-hours">${e.streamHours || 0}h en vivo</div>
      </div>
      ${timeline}
    </article>`;
  }).join('');
}

async function refreshStreamerRanking() {
  const view = document.getElementById('view-ranking');
  if (!view || !view.classList.contains('active')) return;
  try {
    const r = await fetch(`/api/streamer-rankings?type=${encodeURIComponent(srkType)}&limit=${srkLimit()}`);
    if (!r.ok) throw new Error('http');
    renderStreamerRanking(await r.json());
  } catch {
    renderStreamerRanking(null);
  }
}

function setupStreamerRanking() {
  if (srkWired) return;
  srkWired = true;
  try {
    const saved = localStorage.getItem('livecoins-srk-limit');
    const lim = document.getElementById('srk-limit');
    if (lim && saved) lim.value = saved;
  } catch {}
  document.querySelectorAll('.srk-tab').forEach((btn) => {
    btn.onclick = () => {
      document.querySelectorAll('.srk-tab').forEach((b) => b.classList.remove('active'));
      btn.classList.add('active');
      srkType = btn.dataset.srk === 'diamonds' ? 'diamonds' : 'likes';
      refreshStreamerRanking();
    };
  });
  const lim = document.getElementById('srk-limit');
  if (lim) {
    lim.onchange = () => {
      try { localStorage.setItem('livecoins-srk-limit', String(srkLimit())); } catch {}
      refreshStreamerRanking();
    };
  }
  if (srkTimer) clearInterval(srkTimer);
  srkTimer = setInterval(refreshStreamerRanking, 25000);
}

function panelLiveImgUrl(u) {
  if (!u) return '';
  const s = String(u).trim();
  if (!s) return '';
  if (s.startsWith('/api/img-proxy')) return s;
  if (/^https?:\/\//i.test(s)) {
    if (s.startsWith(location.origin)) return s;
    return '/api/img-proxy?url=' + encodeURIComponent(s);
  }
  if (s.startsWith('//')) return '/api/img-proxy?url=' + encodeURIComponent('https:' + s);
  return s;
}

function openPanelLiveUrl(url) {
  const u = String(url || '').trim();
  if (!u) return;
  if (IS_DESKTOP && window.desktopAPI?.openExternal) {
    window.desktopAPI.openExternal(u);
    return;
  }
  window.open(u, '_blank', 'noopener,noreferrer');
}

function panelLiveFallbackChar(name) {
  const ch = String(name || '?').trim()[0];
  return ch ? ch.toUpperCase() : '?';
}

/** Lives del directorio: el servidor ya filtró; no ocultar por viewers=0. */
function isActivePanelLive(l) {
  return !!(l && (l.tiktok || l.account));
}

function isPanelLivePremium(plan) {
  const p = String(plan || 'free').toLowerCase();
  return p === 'premium' || p === 'admin' || p === 'founder';
}

function panelLiveTierLabel(plan) {
  const p = String(plan || 'free').toLowerCase();
  if (p === 'founder') return 'Founder';
  if (isPanelLivePremium(p)) return 'VIP';
  return 'Free';
}

/** Mapa username/tiktok → plan, rellenado desde admin (y usable al pintar lives). */
function rememberPanelLivePlansFromUsers(users) {
  const map = window.__panelLivePlanMap || new Map();
  for (const u of users || []) {
    let plan = 'free';
    if (u?.isAdmin || u?.plan === 'admin') plan = 'premium';
    else if (u?.plan === 'founder') plan = 'founder';
    else if (u?.plan === 'premium') plan = 'premium';
    const name = String(u?.username || '').trim().toLowerCase();
    if (name) map.set(name, plan);
    const acc = String(u?.account || '').replace(/^@+/, '').trim().toLowerCase();
    if (acc) map.set(acc, plan);
  }
  window.__panelLivePlanMap = map;
  return map;
}

function applyPanelLivePlanMap(lives, map) {
  if (!map || !map.size) return lives || [];
  return (lives || []).map((l) => {
    const cur = String(l.plan || '').toLowerCase();
    if (cur === 'founder') return { ...l, plan: 'founder' };
    if (isPanelLivePremium(l.plan)) return { ...l, plan: 'premium' };
    const byUser = map.get(String(l.panelUser || '').trim().toLowerCase());
    const byTt = map.get(String(l.tiktok || l.account || '').replace(/^@+/, '').trim().toLowerCase());
    const pick = byUser || byTt;
    if (pick === 'founder') return { ...l, plan: 'founder' };
    const plan = (pick === 'premium') ? 'premium' : (l.plan || 'free');
    return { ...l, plan };
  });
}

async function enrichPanelLivesWithKnownPlans(lives) {
  let list = lives || [];
  let map = window.__panelLivePlanMap;
  const needs = list.some((l) => !isPanelLivePremium(l.plan));
  if (needs && window.IS_ADMIN) {
    try {
      const r = await fetch('/api/admin/users', { credentials: 'same-origin', cache: 'no-store' });
      if (r.ok) {
        const d = await r.json();
        map = rememberPanelLivePlansFromUsers(d.users || []);
      }
    } catch { /* sin admin */ }
  }
  return applyPanelLivePlanMap(list, map);
}

function renderHomeBadges(badges) {
  const sec = document.getElementById('home-badges');
  const grid = document.getElementById('home-badges-grid');
  const sub = document.getElementById('home-badges-sub');
  if (!sec || !grid) return;
  const list = Array.isArray(badges) ? badges : [];
  if (!list.length) { sec.hidden = true; grid.innerHTML = ''; return; }
  sec.hidden = false;
  const earned = list.filter((b) => b.earned).length;
  if (sub) {
    sub.innerHTML = `<span class="home-badges-count"><strong>${earned}</strong>/${list.length}</span>`
      + `<span class="home-badges-hint">Live ≥15 min cuenta 1 por día</span>`;
  }
  grid.innerHTML = list.map((b) => {
    const prog = b.progress;
    const cur = prog ? Number(prog.current) || 0 : (b.earned ? 1 : 0);
    const tgt = prog && prog.target ? Number(prog.target) || 1 : 1;
    const pct = Math.min(100, Math.round((cur / tgt) * 100));
    const progTxt = prog && prog.target
      ? `${prog.current} / ${prog.target}`
      : (b.earned ? 'Desbloqueada' : 'Bloqueada');
    const img = b.img || badgeArtUrl(b.id);
    const ico = img
      ? `<img class="home-badge-ico-img" src="${esc(img)}" alt="" width="56" height="56" loading="lazy" decoding="async">`
      : `<span class="home-badge-ico">${esc(b.icon || '🏅')}</span>`;
    const status = b.earned ? 'Desbloqueada' : 'Bloqueada';
    return `<article class="home-badge${b.earned ? ' is-earned' : ''}" title="${esc(b.desc || '')}" aria-label="${esc(b.name || b.id)} · ${status}">
      <div class="home-badge-medal">${ico}</div>
      <div class="home-badge-body">
        <h4 class="home-badge-name">${esc(b.name || b.id)}</h4>
        <p class="home-badge-desc">${esc(b.desc || '')}</p>
      </div>
      <div class="home-badge-foot">
        <div class="home-badge-bar" role="progressbar" aria-valuenow="${pct}" aria-valuemin="0" aria-valuemax="100"><span style="width:${pct}%"></span></div>
        <div class="home-badge-prog">${esc(progTxt)}</div>
      </div>
    </article>`;
  }).join('');
}

function renderPanelLives(lives) {
  const sec = $('panel-lives');
  const track = $('panel-lives-track');
  const empty = document.getElementById('home-lives-empty');
  const countEl = document.getElementById('panel-lives-count');
  if (!sec || !track) return;
  // Evita ventanas huérfanas al re-render (refresh cada 25s)
  forceClosePanelLiveBadgePops();
  const active = applyPanelLivePlanMap((lives || []).filter(isActivePanelLive), window.__panelLivePlanMap);
  if (!active.length) {
    sec.hidden = true;
    track.innerHTML = '';
    if (empty) empty.hidden = false;
    if (countEl) { countEl.hidden = true; countEl.textContent = ''; }
    return;
  }
  sec.hidden = false;
  if (empty) empty.hidden = true;
  if (countEl) {
    countEl.hidden = false;
    countEl.textContent = active.length === 1 ? '1 en vivo' : `${active.length} en vivo`;
  }
  track.innerHTML = active.map((l) => {
    const tiktok = String(l.tiktok || l.account || '').replace(/^@+/, '');
    const name = esc(l.nickname || tiktok || l.panelUser || 'Live');
    const viewers = fmt(Number(l.viewers) || 0);
    const liveUrl = l.url || (`https://www.tiktok.com/@${encodeURIComponent(tiktok)}/live`);
    const url = esc(liveUrl);
    const fallback = esc(panelLiveFallbackChar(l.nickname || tiktok || name));
    const photo = panelLiveImgUrl(l.photo || '');
    const premium = isPanelLivePremium(l.plan);
    const isFounder = String(l.plan || '').toLowerCase() === 'founder';
    const tierClass = isFounder
      ? 'panel-live-card--founder'
      : (premium ? 'panel-live-card--vip' : 'panel-live-card--free');
    const tierLabel = panelLiveTierLabel(l.plan);
    const av = photo
      ? `<img class="panel-live-av" src="${esc(photo)}" alt="" loading="eager" decoding="async" referrerpolicy="no-referrer" data-fallback="${fallback}">`
      : `<span class="panel-live-av panel-live-av-ph">${fallback}</span>`;
    const cardBadges = Array.isArray(l.badges) ? l.badges : [];
    const earnedIds = new Set(cardBadges.map((b) => b.id).filter(Boolean));
    const PANEL_BADGE_FALLBACK = [
      { id: 'first_live', name: 'Primera live' },
      { id: 'lives_10', name: 'En marcha' },
      { id: 'lives_50', name: 'Constante' },
      { id: 'lives_100', name: 'Veterano' },
      { id: 'lives_500', name: 'Leyenda' },
      { id: 'streak_3', name: 'Racha 3' },
      { id: 'streak_7', name: 'Racha 7' },
      { id: 'on_map', name: 'En el mapa' },
      { id: 'popular', name: 'Popular' },
      { id: 'daily_top', name: 'Foco de la noche' },
      { id: 'vip', name: 'VIP' },
      { id: 'desktop', name: 'App PC' },
      { id: 'gamer', name: 'Gamer' },
      { id: 'partner', name: 'Partner' },
      { id: 'beta', name: 'Beta' },
      { id: 'staff', name: 'Staff' },
    ];
    const allBadges = Array.isArray(l.allBadges) && l.allBadges.length
      ? l.allBadges
      : PANEL_BADGE_FALLBACK.map((b) => ({
          ...b,
          img: badgeArtUrl(b.id),
          earned: earnedIds.has(b.id),
        }));
    const badgeIcons = cardBadges.map((b) => {
      const src = badgeArtUrl(b.id) || b.img || '';
      const label = esc(b.name || b.short || '');
      if (src) {
        return `<img class="panel-live-mini-badge-img" src="${esc(src)}" alt="${label}" title="${label}" width="18" height="18" loading="lazy" decoding="async">`;
      }
      return `<span class="panel-live-mini-badge" title="${label}">${esc(b.icon || '🏅')}</span>`;
    }).join('');
    const popIcons = allBadges.map((b) => {
      const src = badgeArtUrl(b.id) || b.img || '';
      const label = esc(b.name || b.short || '');
      const earned = !!b.earned;
      const img = src
        ? `<img class="panel-live-mini-badge-img" src="${esc(src)}" alt="${label}" width="26" height="26" loading="lazy" decoding="async">`
        : `<span class="panel-live-mini-badge">${esc(b.icon || '🏅')}</span>`;
      return `<span class="panel-live-pop-item${earned ? ' is-earned' : ' is-locked'}" title="${label}${earned ? '' : ' (pendiente)'}">${img}<span class="panel-live-pop-name">${label}</span></span>`;
    }).join('');
    const hasAny = cardBadges.length || allBadges.length;
    const badgesHtml = hasAny
      ? `<span class="panel-live-badges" aria-label="Insignias" data-has-catalog="1">
          <span class="panel-live-badges-row">${badgeIcons}</span>
          <button type="button" class="panel-live-badges-more-btn" aria-expanded="false" aria-label="Ver todas las insignias" title="Ver todas">›</button>
          <span class="panel-live-badges-pop" hidden role="dialog" aria-label="Todas las insignias">${popIcons}</span>
        </span>`
      : '<span class="panel-live-badges panel-live-badges--empty" aria-hidden="true"></span>';
    return `<a class="panel-live-card ${tierClass}" href="${url}" data-live-url="${url}" target="_blank" rel="noopener noreferrer" title="Ver live de @${esc(tiktok)}">
      ${av}
      <span class="panel-live-main">
        <span class="panel-live-headrow">
          <span class="panel-live-id">
            <span class="panel-live-name">${name}</span>
            <span class="panel-live-user">@${esc(tiktok)}</span>
          </span>
          <span class="panel-live-status">
            <span class="panel-live-tier">${tierLabel}</span>
            <span class="panel-live-badge">EN LIVE</span>
          </span>
        </span>
        ${badgesHtml}
        <span class="panel-live-viewers"><span class="panel-live-viewers-ic" aria-hidden="true"></span>${viewers}</span>
      </span>
    </a>`;
  }).join('');
  track.querySelectorAll('.panel-live-av').forEach((el) => {
    if (el.tagName !== 'IMG') return;
    el.onerror = () => {
      const ph = document.createElement('span');
      ph.className = 'panel-live-av panel-live-av-ph';
      ph.textContent = el.dataset.fallback || '?';
      el.replaceWith(ph);
    };
  });
  setupPanelLiveBadgeTrays(track);
}

/** Cierra y limpia TODOS los popovers (incluye huérfanos en body). */
function forceClosePanelLiveBadgePops() {
  document.querySelectorAll('.panel-live-badges.is-open').forEach((tray) => {
    tray.classList.remove('is-open');
    const btn = tray.querySelector('.panel-live-badges-more-btn');
    if (btn) btn.setAttribute('aria-expanded', 'false');
  });
  document.querySelectorAll('.panel-live-card.is-badges-open').forEach((card) => {
    card.classList.remove('is-badges-open');
  });
  document.querySelectorAll('.panel-live-badges-pop').forEach((pop) => {
    pop.hidden = true;
    pop.classList.remove('panel-live-badges-pop--portal', 'is-visible');
    pop.style.cssText = '';
    if (pop.parentElement === document.body) pop.remove();
  });
  window.__panelLiveBadgeOpenTray = null;
}

function closePanelLiveBadgePops(except) {
  if (!except) {
    forceClosePanelLiveBadgePops();
    return;
  }
  document.querySelectorAll('.panel-live-badges.is-open').forEach((tray) => {
    if (tray === except) return;
    tray.classList.remove('is-open');
    const card = tray.closest('.panel-live-card');
    if (card) card.classList.remove('is-badges-open');
    const btn = tray.querySelector('.panel-live-badges-more-btn');
    if (btn) btn.setAttribute('aria-expanded', 'false');
  });
  document.querySelectorAll('.panel-live-badges-pop').forEach((pop) => {
    if (except._popEl && pop === except._popEl) return;
    if (except.contains(pop)) return;
    pop.hidden = true;
    pop.classList.remove('panel-live-badges-pop--portal', 'is-visible');
    pop.style.cssText = '';
    if (pop.parentElement === document.body) pop.remove();
  });
}

function placePanelLiveBadgePop(tray) {
  let pop = tray._popEl;
  if (!pop || !document.contains(pop)) {
    pop = tray.querySelector('.panel-live-badges-pop');
  }
  if (!pop) return null;
  tray._popEl = pop;
  tray._popHome = tray;
  // Clonar al body para no perderlo si el track se re-renderiza a medias
  if (pop.parentElement !== document.body) {
    const portal = pop.cloneNode(true);
    portal.classList.add('panel-live-badges-pop--portal');
    pop.hidden = true;
    document.body.appendChild(portal);
    tray._popEl = portal;
    tray._popSource = pop;
    pop = portal;
  } else {
    pop.classList.add('panel-live-badges-pop--portal');
  }
  pop.hidden = false;
  pop.classList.add('is-visible');
  const r = tray.getBoundingClientRect();
  const width = Math.min(Math.max(r.width, 260), Math.min(300, window.innerWidth - 16));
  let left = r.left;
  if (left + width > window.innerWidth - 8) left = Math.max(8, window.innerWidth - width - 8);
  const preferUp = r.top > 180;
  pop.style.position = 'fixed';
  pop.style.left = `${Math.round(left)}px`;
  pop.style.width = `${Math.round(width)}px`;
  pop.style.right = 'auto';
  pop.style.zIndex = '10050';
  if (preferUp) {
    pop.style.bottom = `${Math.round(window.innerHeight - r.top + 8)}px`;
    pop.style.top = 'auto';
  } else {
    pop.style.top = `${Math.round(r.bottom + 8)}px`;
    pop.style.bottom = 'auto';
  }
  window.__panelLiveBadgeOpenTray = tray;
  return pop;
}

function openPanelLiveBadgePop(tray) {
  forceClosePanelLiveBadgePops();
  const btn = tray.querySelector('.panel-live-badges-more-btn');
  const card = tray.closest('.panel-live-card');
  tray.classList.add('is-open');
  if (card) card.classList.add('is-badges-open');
  if (btn) btn.setAttribute('aria-expanded', 'true');
  placePanelLiveBadgePop(tray);
}

function togglePanelLiveBadgePop(tray) {
  if (tray.classList.contains('is-open') || window.__panelLiveBadgeOpenTray === tray) {
    forceClosePanelLiveBadgePops();
    return;
  }
  openPanelLiveBadgePop(tray);
}

function fitPanelLiveBadgeTray(tray) {
  if (!tray || tray.classList.contains('panel-live-badges--empty')) return;
  const row = tray.querySelector('.panel-live-badges-row');
  const btn = tray.querySelector('.panel-live-badges-more-btn');
  if (!row || !btn) return;
  const items = [...row.children];
  const hasCatalog = tray.dataset.hasCatalog === '1';

  items.forEach((el) => { el.hidden = false; });

  if (hasCatalog) {
    btn.hidden = false;
    tray.classList.add('has-more');
    btn.textContent = '›';
    btn.title = 'Ver todas las insignias';
    btn.setAttribute('aria-label', 'Ver todas las insignias');
    if (items.length && row.scrollWidth > row.clientWidth + 1) {
      for (let i = items.length - 1; i >= 0; i--) {
        if (row.scrollWidth <= row.clientWidth + 1) break;
        items[i].hidden = true;
      }
      if (items.every((el) => el.hidden) && items[0]) items[0].hidden = false;
    }
    return;
  }

  btn.hidden = true;
  tray.classList.remove('has-more');
  if (row.scrollWidth <= row.clientWidth + 1) return;
  btn.hidden = false;
  tray.classList.add('has-more');
  for (let i = items.length - 1; i >= 0; i--) {
    if (row.scrollWidth <= row.clientWidth + 1) break;
    items[i].hidden = true;
  }
  if (items.every((el) => el.hidden) && items[0]) items[0].hidden = false;
  const hiddenCount = items.filter((el) => el.hidden).length;
  if (!hiddenCount) {
    btn.hidden = true;
    tray.classList.remove('has-more');
    return;
  }
  btn.textContent = '›';
  btn.title = `Ver ${hiddenCount} más`;
  btn.setAttribute('aria-label', `Ver ${hiddenCount} insignias más`);
}

function setupPanelLiveBadgeTrays(root) {
  const host = root || document;
  host.querySelectorAll('.panel-live-badges').forEach((tray) => {
    fitPanelLiveBadgeTray(tray);
    tray.querySelectorAll('.panel-live-badges-row img').forEach((img) => {
      if (img.complete) return;
      img.addEventListener('load', () => fitPanelLiveBadgeTray(tray), { once: true });
    });
  });

  // Captura: la flecha NO debe abrir el live (el listener del track está en bubble)
  if (host.addEventListener && !host._badgeTrayDelegated) {
    host._badgeTrayDelegated = true;
    host.addEventListener('click', (e) => {
      const btn = e.target.closest('.panel-live-badges-more-btn');
      if (!btn || !host.contains(btn)) return;
      e.preventDefault();
      e.stopPropagation();
      e.stopImmediatePropagation();
      const tray = btn.closest('.panel-live-badges');
      if (!tray) return;
      togglePanelLiveBadgePop(tray);
    }, true);
  }

  if (!window._panelLiveBadgePopClose) {
    window._panelLiveBadgePopClose = true;
    document.addEventListener('pointerdown', (e) => {
      if (!window.__panelLiveBadgeOpenTray && !document.querySelector('.panel-live-badges-pop--portal')) return;
      if (e.target.closest('.panel-live-badges-more-btn')) return;
      if (e.target.closest('.panel-live-badges-pop')) return;
      forceClosePanelLiveBadgePops();
    }, true);
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') forceClosePanelLiveBadgePops();
    });
    window.addEventListener('resize', () => forceClosePanelLiveBadgePops());
    window.addEventListener('scroll', () => forceClosePanelLiveBadgePops(), true);
    document.addEventListener('visibilitychange', () => {
      if (document.hidden) forceClosePanelLiveBadgePops();
    });
  }
}
async function refreshPanelLives() {
  // Preferir /api/panel-lives (local o proxy) para que el plan venga resuelto.
  // La pública de la nube queda de respaldo (p. ej. .exe sin cookie).
  const urls = ['/api/panel-lives'];
  try {
    if (IS_DESKTOP && window.desktopAPI?.cloudBase) {
      urls.push(String(window.desktopAPI.cloudBase).replace(/\/+$/, '') + '/api/panel-lives-public');
    }
  } catch { /* sin cloudBase */ }
  for (const url of urls) {
    try {
      const r = await fetch(url, { credentials: url.startsWith('http') ? 'omit' : 'same-origin', cache: 'no-store' });
      if (!r.ok) continue;
      const d = await r.json();
      if (!Array.isArray(d.lives)) continue;
      const lives = await enrichPanelLivesWithKnownPlans(d.lives);
      window.__lastPanelLives = lives;
      renderPanelLives(lives);
      return;
    } catch { /* siguiente URL */ }
  }
}
function setupPanelLives() {
  const track = $('panel-lives-track');
  if (track && !track._panelLiveClick) {
    track._panelLiveClick = true;
    track.addEventListener('click', (e) => {
      if (e.target.closest('.panel-live-badges-more-btn, .panel-live-badges-pop')) return;
      const card = e.target.closest('.panel-live-card');
      if (!card) return;
      e.preventDefault();
      openPanelLiveUrl(card.dataset.liveUrl || card.getAttribute('href'));
    });
  }
  refreshPanelLives();
  if (panelLivesTimer) clearInterval(panelLivesTimer);
  panelLivesTimer = setInterval(refreshPanelLives, 25000);
}

